window.EXERCISES = [{"id":"smith-ohp","name":"Smith Machine Overhead Press","group":"Shoulders","primary":["Front delts","Side delts"],"secondary":["Triceps","Upper chest"],"equip":"Smith","tip":"Bar in line with your nose at the bottom; press slightly back, not forward.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/smith-ohp-0.jpg","img/smith-ohp-1.jpg"],"steps":["To begin, place a flat bench (or preferably one with back support) underneath a smith machine. Position the barbell at a height so that when seated on the flat bench, the arms must be almost fully extended to reach the barbell.","Once you have the correct height, sit slightly in behind the barbell so that there is an imaginary straight line from the tip of your nose to the barbell. Your feet should be stationary. Grab the barbell with the palms facing forward, unlock it and lift it up so that your arms are fully extended. This is the starting position.","Slowly begin to lower the barbell until it is level with your chin while inhaling.","Then lift the barbell back to the starting position using your shoulders while exhaling.","Repeat for the recommended amount of repetitions."],"video":"kYZ0aUEzgEQ"},{"id":"barbell-ohp","name":"Barbell Overhead Press","group":"Shoulders","primary":["Front delts","Side delts"],"secondary":["Triceps","Upper chest","Core"],"equip":"Barbell","tip":"Squeeze glutes, ribs down, press and bring your head through at the top.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/barbell-ohp-0.jpg","img/barbell-ohp-1.jpg"],"steps":["Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.","Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.","Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.","Lower the bar down to the collarbone slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."],"video":"nNMR9fRGRjQ"},{"id":"db-shoulder-press","name":"Dumbbell Shoulder Press","group":"Shoulders","primary":["Front delts","Side delts"],"secondary":["Triceps"],"equip":"Dumbbell","tip":"Elbows slightly in front of your body, not flared straight out.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/db-shoulder-press-0.jpg","img/db-shoulder-press-1.jpg"],"steps":["While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.","Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.","Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.","Now, exhale and push the dumbbells upward until they touch at the top.","Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"video":"vlFGTI5JzjI"},{"id":"arnold-press","name":"Arnold Press","group":"Shoulders","primary":["Front delts","Side delts"],"secondary":["Triceps"],"equip":"Dumbbell","tip":"Start palms facing you, rotate out as you press.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/arnold-press-0.jpg","img/arnold-press-1.jpg"],"steps":["Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.","Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.","Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.","After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"video":"hNkDPoM3Oro"},{"id":"machine-shoulder-press","name":"Machine Shoulder Press","group":"Shoulders","primary":["Front delts","Side delts"],"secondary":["Triceps"],"equip":"Machine","tip":"Set the seat so the handles start at ear height.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/machine-shoulder-press-0.jpg","img/machine-shoulder-press-1.jpg"],"steps":["Sit down on the Shoulder Press Machine and select the weight.","Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.","Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.","Lower the handles slowly back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"video":"Anu8s_nkNpM"},{"id":"cable-lateral-raise","name":"Cable Lateral Raise","group":"Shoulders","primary":["Side delts"],"secondary":[],"equip":"Cable","tip":"Cable at the lowest setting, lead with the elbow, stop at shoulder height.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/cable-lateral-raise-0.jpg","img/cable-lateral-raise-1.jpg"],"steps":["Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.","Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.","Bend forward while keeping your back flat and rest your torso on the thighs.","Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.","While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.","Slowly lower your arms to the starting position as you inhale."],"video":"-CAGLnWUkWA"},{"id":"db-lateral-raise","name":"Dumbbell Lateral Raise","group":"Shoulders","primary":["Side delts"],"secondary":[],"equip":"Dumbbell","tip":"Slight bend in the elbow, pour the water out of the jug at the top.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/db-lateral-raise-0.jpg","img/db-lateral-raise-1.jpg"],"steps":["Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.","While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.","Lower the dumbbells back down slowly to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"video":"XPPfnSEATJA"},{"id":"front-raise","name":"Front Raise","group":"Shoulders","primary":["Front delts"],"secondary":["Upper chest"],"equip":"Dumbbell","tip":"Raise to eye level, no swinging. Dumbbells or a plate.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/front-raise-0.jpg","img/front-raise-1.jpg"],"steps":["Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.","Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.","Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm."],"video":"zkP0MsTcIVU"},{"id":"reverse-pec-deck","name":"Reverse Pec Deck Fly","group":"Shoulders","primary":["Rear delts"],"secondary":["Upper back","Mid traps"],"equip":"Machine","tip":"Handles at shoulder height; drive elbows back, don't squeeze shoulder blades too hard.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/reverse-pec-deck-0.jpg","img/reverse-pec-deck-1.jpg"],"steps":["Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.","In a semicircular motion, pull your hands out to your side and back, contracting your rear delts.","Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.","Pause at the rear of the movement, and slowly return the weight to the starting position."],"video":"e4dJ1QoxUtI"},{"id":"cable-rear-delt-fly","name":"Cable Rear-Delt Fly","group":"Shoulders","primary":["Rear delts"],"secondary":["Upper back"],"equip":"Cable","tip":"Cross the cables, pull wide with straight-ish arms.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/cable-rear-delt-fly-0.jpg","img/cable-rear-delt-fly-1.jpg"],"steps":["Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.","Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.","Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.","Pause at the end of the motion before returning the handles to the start position."]},{"id":"face-pull","name":"Face Pull","group":"Shoulders","primary":["Rear delts","Rotator cuff"],"secondary":["Upper back","Mid traps"],"equip":"Cable","tip":"Rope at face height; pull to the forehead with thumbs pointing back.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/face-pull-0.jpg","img/face-pull-1.jpg"],"steps":["Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground."]},{"id":"db-shrug","name":"Dumbbell Shrug","group":"Shoulders","primary":["Upper traps"],"secondary":["Grip"],"equip":"Dumbbell","tip":"Straight up and down — no rolling. Hold the top for a second.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/db-shrug-0.jpg","img/db-shrug-1.jpg"],"steps":["Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.","Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.","Lower the dumbbells back to the original position.","Repeat for the recommended amount of repetitions."],"video":"qvvJUKq7_sU"},{"id":"bayesian-curl","name":"Bayesian Cable Curl","group":"Biceps","primary":["Biceps (long head)"],"secondary":["Brachialis"],"equip":"Cable","tip":"Face away from the low cable, arm behind your body, curl without moving the elbow forward.","mine":true,"track":"weight","alt":[],"aka":[],"img":[],"steps":[],"video":"S6HnE1fDlaI"},{"id":"cable-bar-curl","name":"Cable Bar Curl","group":"Biceps","primary":["Biceps"],"secondary":["Forearms"],"equip":"Cable","tip":"Straight or EZ bar on the low pulley; elbows pinned to your sides.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/cable-bar-curl-0.jpg","img/cable-bar-curl-1.jpg"],"steps":["Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the curl bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"video":"d7friQusjF8"},{"id":"cable-hammer-curl","name":"Cable Hammer Curl (rope)","group":"Biceps","primary":["Brachialis","Biceps"],"secondary":["Forearms (brachioradialis)"],"equip":"Cable","tip":"Thumbs up the whole way; pull the rope ends apart at the top.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/cable-hammer-curl-0.jpg","img/cable-hammer-curl-1.jpg"],"steps":["Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.","Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.","Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.","Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.","After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.","Repeat for the recommended amount of repetitions."],"video":"vsarApmqJmo"},{"id":"preacher-curl","name":"Preacher Curl","group":"Biceps","primary":["Biceps (short head)"],"secondary":["Brachialis"],"equip":"Machine","tip":"Machine, EZ bar or dumbbell. Don't fully lock out at the bottom.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/preacher-curl-0.jpg","img/preacher-curl-1.jpg"],"steps":["To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.","With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.","As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.","Repeat for the recommended amount of repetitions."],"video":"to3m8zws1n8"},{"id":"db-curl","name":"Dumbbell Curl","group":"Biceps","primary":["Biceps"],"secondary":["Forearms"],"equip":"Dumbbell","tip":"Rotate the pinky up as you curl (supinate).","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/db-curl-0.jpg","img/db-curl-1.jpg"],"steps":["Stand up straight with a dumbbell in each hand at arm's length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]},{"id":"incline-db-curl","name":"Incline Dumbbell Curl","group":"Biceps","primary":["Biceps (long head)"],"secondary":[],"equip":"Dumbbell","tip":"Bench at ~45°, arms hanging straight back — big stretch at the bottom.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/incline-db-curl-0.jpg","img/incline-db-curl-1.jpg"],"steps":["Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.","While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.","Slowly begin to bring the dumbbells back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."]},{"id":"ez-bar-curl","name":"EZ-Bar Curl","group":"Biceps","primary":["Biceps"],"secondary":["Forearms"],"equip":"Barbell","tip":"Easier on the wrists than a straight bar.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/ez-bar-curl-0.jpg","img/ez-bar-curl-1.jpg"],"steps":["Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.","Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.","Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.","Then inhale and slowly lower the bar back to the starting position.","Repeat for the recommended amount of repetitions."]},{"id":"concentration-curl","name":"Concentration Curl","group":"Biceps","primary":["Biceps (short head)"],"secondary":[],"equip":"Dumbbell","tip":"Elbow braced against the inner thigh; squeeze hard at the top.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/concentration-curl-0.jpg","img/concentration-curl-1.jpg"],"steps":["Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.","Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.","While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.","Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm."]},{"id":"spider-curl","name":"Spider Curl","group":"Biceps","primary":["Biceps (short head)"],"secondary":[],"equip":"Dumbbell","tip":"Chest on an incline bench, arms hanging straight down.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/spider-curl-0.jpg","img/spider-curl-1.jpg"],"steps":["Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off.","Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench.","Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arms on top of the pad located on the inside part of the preacher bench.","Use your arms to grab the barbell with a supinated grip (palms facing up) at about shoulder width apart or slightly closer from each other.","Slowly begin to lift the barbell upwards and exhale. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the barbell back to the starting position as your breathe in. ."]},{"id":"hammer-curl","name":"Dumbbell Hammer Curl","group":"Biceps","primary":["Brachialis","Biceps"],"secondary":["Forearms (brachioradialis)"],"equip":"Dumbbell","tip":"Neutral grip, thumbs up.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/hammer-curl-0.jpg","img/hammer-curl-1.jpg"],"steps":["Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.","The palms of the hands should be facing your torso. This will be your starting position.","Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.","After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.","Repeat for the recommended amount of repetitions."]},{"id":"reverse-curl","name":"Reverse Curl (overhand)","group":"Forearms","primary":["Forearms (brachioradialis)"],"secondary":["Biceps","Brachialis"],"equip":"Barbell","tip":"Palms down, EZ bar or straight bar. Light weight, strict.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/reverse-curl-0.jpg","img/reverse-curl-1.jpg"],"steps":["Stand up with your torso upright while holding a barbell at shoulder width with the elbows close to the torso. The palm of your hands should be facing down (pronated grip). This will be your starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."]},{"id":"triceps-pushdown","name":"Cable Triceps Pushdown","group":"Triceps","primary":["Triceps"],"secondary":[],"equip":"Cable","tip":"Rope or bar. Elbows stay by your sides; rope = pull apart at the bottom.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/triceps-pushdown-0.jpg","img/triceps-pushdown-1.jpg"],"steps":["Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).","Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.","Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.","After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.","Repeat for the recommended amount of repetitions."],"video":"_w-HpW70nSQ"},{"id":"single-arm-pushdown","name":"Single-Arm Cable Pushdown","group":"Triceps","primary":["Triceps"],"secondary":[],"equip":"Cable","tip":"One handle; fixes left/right imbalance. Stand side-on to the cable.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/single-arm-pushdown-0.jpg","img/single-arm-pushdown-1.jpg"],"steps":["With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.","Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This will be your starting position.","As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Breathe out as you perform this movement. Tip: Only the forearms should move. Your upper arms should remain stationary at all times.","Squeeze the triceps and hold for a second in this contracted position.","Slowly return the handle to the starting position.","Repeat for the recommended amount of repetitions and then perform the same movement with the other arm."],"video":"YZngJdQ71k0"},{"id":"overhead-cable-ext","name":"Overhead Cable Triceps Extension","group":"Triceps","primary":["Triceps (long head)"],"secondary":[],"equip":"Cable","tip":"Rope, face away from the cable, elbows by your ears. This is the head pushdowns miss.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/overhead-cable-ext-0.jpg","img/overhead-cable-ext-1.jpg"],"steps":["Attach a rope to the bottom pulley of the pulley machine.","Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.","Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.","Return to the starting position by flexing your triceps as you breathe out.","Repeat for the recommended amount of repetitions."]},{"id":"overhead-db-ext","name":"Overhead Dumbbell Triceps Extension","group":"Triceps","primary":["Triceps (long head)"],"secondary":[],"equip":"Dumbbell","tip":"One dumbbell with both hands, lower behind the head, elbows pointing up.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/overhead-db-ext-0.jpg","img/overhead-db-ext-1.jpg"],"steps":["To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended.","The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position.","Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions."]},{"id":"skull-crusher","name":"Skull Crusher","group":"Triceps","primary":["Triceps (long head)"],"secondary":[],"equip":"Barbell","tip":"EZ bar, lower to the forehead or just behind it; elbows stay still.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/skull-crusher-0.jpg","img/skull-crusher-1.jpg"],"steps":["Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.","Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.","Lift the bar back to the starting position by extending the elbow and exhaling.","Repeat."]},{"id":"close-grip-bench","name":"Close-Grip Bench Press","group":"Triceps","primary":["Triceps"],"secondary":["Mid chest","Front delts"],"equip":"Barbell","tip":"Hands about shoulder width (not touching), elbows tucked.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/close-grip-bench-0.jpg","img/close-grip-bench-1.jpg"],"steps":["Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."]},{"id":"dips-triceps","name":"Dips (upright, triceps)","group":"Triceps","primary":["Triceps"],"secondary":["Lower chest","Front delts"],"equip":"Bodyweight","tip":"Stay upright, elbows back; add a belt or use the assisted machine.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/dips-triceps-0.jpg","img/dips-triceps-1.jpg"],"steps":["To get into the starting position, hold your body at arm's length with your arms nearly locked above the bars.","Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.","Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.","Repeat the movement for the prescribed amount of repetitions."]},{"id":"bench-dip","name":"Bench Dip","group":"Triceps","primary":["Triceps"],"secondary":["Front delts","Chest"],"equip":"Bodyweight","tip":"Keep your back close to the bench and stop when your upper arms are level with the floor.","mine":false,"track":"bw","alt":["dips-triceps"],"aka":["chair dip","bench dips"],"img":[],"steps":["Sit on the edge of a bench with your hands next to your hips, fingers pointing forward.","Slide your hips off the bench with your legs out in front, knees bent (straight legs make it harder).","Bend your elbows straight back and lower your body until your upper arms are about level with the floor.","Push back up until your arms are straight. Repeat."],"video":""},{"id":"wrist-curl","name":"Wrist Curl","group":"Forearms","primary":["Forearm flexors"],"secondary":["Grip"],"equip":"Barbell","tip":"Forearms on a bench, palms up, only the wrist moves.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/wrist-curl-0.jpg","img/wrist-curl-1.jpg"],"steps":["Start out by placing a barbell on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab the barbell with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise."]},{"id":"reverse-wrist-curl","name":"Reverse Wrist Curl","group":"Forearms","primary":["Forearm extensors"],"secondary":[],"equip":"Barbell","tip":"Palms down, light weight, slow.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/reverse-wrist-curl-0.jpg","img/reverse-wrist-curl-1.jpg"],"steps":["Start out by placing a barbell on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab the barbell with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise."]},{"id":"farmers-walk","name":"Farmer's Walk","group":"Forearms","primary":["Grip","Forearms"],"secondary":["Upper traps","Core"],"equip":"Dumbbell","tip":"Heavy dumbbells, tall posture, walk for distance or time.","mine":false,"track":"time","alt":[],"aka":[],"img":["img/farmers-walk-0.jpg","img/farmers-walk-1.jpg"],"steps":["There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren't available. Begin by standing between the implements.","After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.","Walk taking short, quick steps, and don't forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible."]},{"id":"bench-press","name":"Barbell Flat Bench Press","group":"Chest","primary":["Mid chest"],"secondary":["Front delts","Triceps"],"equip":"Barbell","tip":"Feet planted, shoulder blades pinched, bar to the lower chest.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/bench-press-0.jpg","img/bench-press-1.jpg"],"steps":["Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.","After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"video":"4Y2ZdHCOXok"},{"id":"smith-bench","name":"Smith Machine Flat Bench Press","group":"Chest","primary":["Mid chest"],"secondary":["Front delts","Triceps"],"equip":"Smith","tip":"Line the bar up with your nipple line before you unrack.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/smith-bench-0.jpg","img/smith-bench-1.jpg"],"steps":["Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, lock the bar back in the rack."],"video":"8QknvhBGM9A"},{"id":"incline-bench","name":"Barbell Incline Bench Press","group":"Chest","primary":["Upper chest"],"secondary":["Front delts","Triceps"],"equip":"Barbell","tip":"Bench at 30°; bar touches just below the collarbone.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/incline-bench-0.jpg","img/incline-bench-1.jpg"],"steps":["Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on you upper chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"video":"5kyLUGVq_pk"},{"id":"smith-incline-bench","name":"Smith Machine Incline Bench Press","group":"Chest","primary":["Upper chest"],"secondary":["Front delts","Triceps"],"equip":"Smith","tip":"Bench at 30°, set the bench so the bar lands on the upper chest.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/smith-incline-bench-0.jpg","img/smith-incline-bench-1.jpg"],"steps":["Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your upper chest is aligned with the barbell. Using a pronated grip (palms facing forward) that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your upper chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"video":"MqcS3CMGtwQ"},{"id":"incline-db-press","name":"Incline Dumbbell Press","group":"Chest","primary":["Upper chest"],"secondary":["Front delts","Triceps"],"equip":"Dumbbell","tip":"Bench at 30°, dumbbells come together at the top without touching.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/incline-db-press-0.jpg","img/incline-db-press-1.jpg"],"steps":["Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.","Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.","Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.","Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.","Repeat the movement for the prescribed amount of repetitions."],"video":"hChjZQhX1Ls"},{"id":"db-bench-press","name":"Flat Dumbbell Press","group":"Chest","primary":["Mid chest"],"secondary":["Front delts","Triceps"],"equip":"Dumbbell","tip":"Deeper stretch than the bar; keep elbows ~45° from the body.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/db-bench-press-0.jpg","img/db-bench-press-1.jpg"],"steps":["Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.","Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.","Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.","Repeat the movement for the prescribed amount of repetitions of your training program."]},{"id":"machine-chest-press","name":"Machine Chest Press","group":"Chest","primary":["Mid chest"],"secondary":["Front delts","Triceps"],"equip":"Machine","tip":"Set the seat so the handles are at mid-chest height.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/machine-chest-press-0.jpg","img/machine-chest-press-1.jpg"],"steps":["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.","Your chest and head should be up and your shoulder blades retracted. This will be your starting position.","Press the handles forward by extending through the elbow.","After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."]},{"id":"decline-bench","name":"Decline Bench Press","group":"Chest","primary":["Lower chest"],"secondary":["Triceps","Front delts"],"equip":"Barbell","tip":"Bar to the lower chest, short range — go heavier than flat.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/decline-bench-0.jpg","img/decline-bench-1.jpg"],"steps":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.","As you breathe in, come down slowly until you feel the bar on your lower chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."]},{"id":"cable-fly-high","name":"Cable Fly — High to Low","group":"Chest","primary":["Lower chest"],"secondary":["Front delts"],"equip":"Cable","tip":"Pulleys at the top; bring hands down and together in front of your hips.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/cable-fly-high-0.jpg","img/cable-fly-high-1.jpg"],"steps":["To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.","Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions."],"video":"hhruLxo9yZU"},{"id":"cable-fly-mid","name":"Cable Fly — Mid (standing)","group":"Chest","primary":["Mid chest"],"secondary":["Front delts"],"equip":"Cable","tip":"Pulleys at shoulder height; hands meet straight in front of the chest.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/cable-fly-mid-0.jpg","img/cable-fly-mid-1.jpg"],"steps":["Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.","Step forward in front of both pulleys with your arms extended in front of you, bringing your hands together. Your head and chest should be up as you lean forward, while your feet should be staggered. This will be your starting position.","Keeping your left arm in place, allow your right arm to extend out to the side, maintaining a slight bend at the elbow. The right arm should be perpendicular to the body at approximately shoulder level.","Return your arm back to the starting position by pulling your hand back to the midline of the body.","Hold for a second at the starting position and repeat the movement on the opposite side. Continue alternating back and forth for the prescribed number of repetitions."],"video":"FBob-Wfc7ew"},{"id":"cable-fly-low","name":"Cable Fly — Low to High","group":"Chest","primary":["Upper chest"],"secondary":["Front delts"],"equip":"Cable","tip":"Pulleys at the bottom; scoop up to eye level.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/cable-fly-low-0.jpg","img/cable-fly-low-1.jpg"],"steps":["To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.","Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position.","With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up.","Return your arms back to the starting position after a brief pause."],"video":"FBob-Wfc7ew"},{"id":"pec-deck","name":"Pec Deck Fly","group":"Chest","primary":["Mid chest"],"secondary":["Front delts"],"equip":"Machine","tip":"Handles at chest height, slight elbow bend, squeeze for a second at the front.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/pec-deck-0.jpg","img/pec-deck-1.jpg"],"steps":["Sit on the machine with your back flat on the pad.","Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.","Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.","Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.","Repeat for the recommended amount of repetitions."],"video":"ze4JaQCcGLg"},{"id":"db-fly","name":"Dumbbell Fly","group":"Chest","primary":["Mid chest"],"secondary":["Front delts"],"equip":"Dumbbell","tip":"Big arc, don't go too deep; flat or incline bench.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/db-fly-0.jpg","img/db-fly-1.jpg"],"steps":["Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.","Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you're pressing them, but stop and hold just before you lock out. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions."]},{"id":"dips-chest","name":"Dips (leaning, chest)","group":"Chest","primary":["Lower chest"],"secondary":["Triceps","Front delts"],"equip":"Bodyweight","tip":"Lean forward, elbows out a little, go deep.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/dips-chest-0.jpg","img/dips-chest-1.jpg"],"steps":["For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.","While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.","Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.","Repeat the movement for the prescribed amount of repetitions."]},{"id":"db-pullover","name":"Dumbbell Pullover","group":"Chest","primary":["Mid chest","Lats"],"secondary":["Triceps (long head)","Serratus"],"equip":"Dumbbell","tip":"Lying across a bench, lower the dumbbell behind your head with a slight elbow bend.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/db-pullover-0.jpg","img/db-pullover-1.jpg"],"steps":["Place a dumbbell standing up on a flat bench.","Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.","Grasp the dumbbell with both hands and hold it straight over your chest at arms length. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position.\nCaution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.","While keeping your arms straight, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.","At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.","Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions."]},{"id":"knee-push-up","name":"Knee Push-Up","group":"Chest","primary":["Chest"],"secondary":["Triceps","Front delts","Core"],"equip":"Bodyweight","tip":"A straight line from knees to head: hips don't sag or pike.","mine":false,"track":"bw","alt":["push-up"],"aka":["kneeling push up","half push up"],"img":[],"steps":["Kneel on a mat and put your hands on the floor a little wider than your shoulders.","Walk your hands forward until your body makes a straight line from your knees to your head. Brace your stomach.","Bend your elbows and lower your chest until it nearly touches the floor, elbows about 45 degrees from your sides.","Push the floor away until your arms are straight again. Repeat."],"video":""},{"id":"push-up","name":"Push-Up","group":"Chest","primary":["Chest"],"secondary":["Triceps","Front delts","Core"],"equip":"Bodyweight","tip":"Body in one straight line; chest to a fist's height from the floor.","mine":false,"track":"bw","alt":["knee-push-up","decline-push-up"],"aka":["press up","pushup"],"img":[],"steps":["Put your hands on the floor a little wider than your shoulders and step your feet back so your body makes a straight line from head to heels.","Brace your stomach and squeeze your glutes so your hips stay level.","Bend your elbows and lower your chest until it is a fist's height from the floor, elbows about 45 degrees from your sides.","Push the floor away until your arms are straight. Repeat."],"video":""},{"id":"decline-push-up","name":"Decline Push-Up","group":"Chest","primary":["Upper chest","Chest"],"secondary":["Front delts","Triceps","Core"],"equip":"Bodyweight","tip":"Feet on a bench or step; keep the hips in line, not piked.","mine":false,"track":"bw","alt":["push-up"],"aka":["feet elevated push up"],"img":[],"steps":["Put your feet on a bench or a step behind you and your hands on the floor a little wider than your shoulders.","Make a straight line from heels to head and brace your stomach.","Lower your chest towards the floor with your elbows about 45 degrees from your sides.","Push back up until your arms are straight. Repeat."],"video":""},{"id":"archer-push-up","name":"Archer Push-Up","group":"Chest","primary":["Chest"],"secondary":["Triceps","Front delts","Core"],"equip":"Bodyweight","tip":"Most of your weight goes over the bending arm; the other stays straight. Count reps for each side.","mine":false,"track":"bw","alt":["decline-push-up"],"aka":["archer pushup"],"img":[],"steps":["Start in a push-up position with your hands much wider than your shoulders.","Bend one elbow and lower your chest towards that hand while the other arm stays straight and slides out to the side.","Push back up to the middle.","Do the same to the other side. One rep to each side counts as one rep."],"video":""},{"id":"lat-pulldown-wide","name":"Wide-Grip Lat Pulldown","group":"Back","primary":["Lats"],"secondary":["Biceps","Rear delts","Teres major"],"equip":"Cable","tip":"Pull to the upper chest, elbows down and back, slight lean.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/lat-pulldown-wide-0.jpg","img/lat-pulldown-wide-1.jpg"],"steps":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.","After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","Repeat this motion for the prescribed amount of repetitions."],"video":"j6KuKd_N8uU"},{"id":"lat-pulldown-close","name":"Close-Grip Lat Pulldown","group":"Back","primary":["Lats (lower)"],"secondary":["Biceps"],"equip":"Cable","tip":"Narrow overhand grip; pull to the top of the chest.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/lat-pulldown-close-0.jpg","img/lat-pulldown-close-1.jpg"],"steps":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.","After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","6. Repeat this motion for the prescribed amount of repetitions."],"video":"IjoFCmLX7z0"},{"id":"lat-pulldown-neutral","name":"Neutral-Grip (V-bar) Lat Pulldown","group":"Back","primary":["Lats"],"secondary":["Biceps","Mid back"],"equip":"Cable","tip":"Palms facing each other — easiest on the shoulders.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/lat-pulldown-neutral-0.jpg","img/lat-pulldown-neutral-1.jpg"],"steps":["Sit down on a pull-down machine with a V-Bar attached to the top pulley.","Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position.","Using your lats, pull the bar down as you squeeze your shoulder blades. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion. Tip: Keep the torso stationary throughout the movement.","After a second hold on the contracted position, slowly bring the bar back to the starting position as you breathe in.","Repeat for the prescribed number of repetitions."],"video":"j6DGiY4iUmo"},{"id":"lat-pulldown-reverse","name":"Reverse-Grip Lat Pulldown","group":"Back","primary":["Lats (lower)"],"secondary":["Biceps"],"equip":"Cable","tip":"Underhand, shoulder-width; think elbows to the back pockets.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/lat-pulldown-reverse-0.jpg","img/lat-pulldown-reverse-1.jpg"],"steps":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, pull the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the fully contracted position and keep the elbows close to your body. The upper torso should remain stationary as your bring the bar to you and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, while breathing in, slowly bring the bar back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions."],"video":"SNiwpA13ZLU"},{"id":"lat-pulldown-single","name":"Single-Arm Lat Pulldown","group":"Back","primary":["Lats"],"secondary":["Biceps"],"equip":"Cable","tip":"One handle, pull to the side of the chest, full stretch at the top.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/lat-pulldown-single-0.jpg","img/lat-pulldown-single-1.jpg"],"steps":["Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position.","Pull the handle down, squeezing your elbow to your side as you flex the elbow.","Pause at the bottom of the motion, and then slowly return the handle to the starting position.","For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked."],"video":"2qyHRUCuTEo"},{"id":"straight-arm-pulldown","name":"Straight-Arm Cable Pulldown","group":"Back","primary":["Lats"],"secondary":["Triceps (long head)","Rear delts"],"equip":"Cable","tip":"Rope or bar, arms almost straight, sweep down to the thighs. No biceps involved.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/straight-arm-pulldown-0.jpg","img/straight-arm-pulldown-1.jpg"],"steps":["You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.","Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.","While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.","While keeping the arms straight, go back to the starting position while breathing in.","Repeat for the recommended amount of repetitions."],"video":"98W63pVdW38"},{"id":"pull-up","name":"Pull-Up","group":"Back","primary":["Lats"],"secondary":["Biceps","Upper back","Core"],"equip":"Bodyweight","tip":"Overhand. Use the assisted machine or a band if needed; add weight once you get 10+.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/pull-up-0.jpg","img/pull-up-1.jpg"],"steps":["Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions."]},{"id":"chin-up","name":"Chin-Up","group":"Back","primary":["Lats","Biceps"],"secondary":["Upper back"],"equip":"Bodyweight","tip":"Underhand, shoulder-width — more biceps than a pull-up.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/chin-up-0.jpg","img/chin-up-1.jpg"],"steps":["Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.","As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.","Repeat this motion for the prescribed amount of repetitions."]},{"id":"seated-cable-row","name":"Seated Cable Row (V-bar)","group":"Back","primary":["Mid back","Lats"],"secondary":["Biceps","Rear delts"],"equip":"Cable","tip":"Close V-bar to the belly button; chest up, don't lean back past vertical.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/seated-cable-row-0.jpg","img/seated-cable-row-1.jpg"],"steps":["For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.","Lean over as you keep the natural alignment of your back and grab the V-bar handles.","With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.","Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.","Repeat for the recommended amount of repetitions."],"video":"oFtfkSElE0s"},{"id":"seated-cable-row-wide","name":"Seated Cable Row (wide bar)","group":"Back","primary":["Upper back","Rear delts"],"secondary":["Lats","Biceps"],"equip":"Cable","tip":"Wide overhand bar, elbows high, pull to the lower chest.","mine":true,"track":"weight","alt":[],"aka":[],"img":[],"steps":[],"video":"SYZxuSSQ-hk"},{"id":"barbell-row","name":"Barbell Bent-Over Row","group":"Back","primary":["Upper back","Lats"],"secondary":["Rear delts","Biceps","Lower back"],"equip":"Barbell","tip":"Hinge to ~45°, overhand, pull to the lower chest.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/barbell-row-0.jpg","img/barbell-row-1.jpg"],"steps":["Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.","Then inhale and slowly lower the barbell back to the starting position.","Repeat for the recommended amount of repetitions."],"video":"qXrTDQG1oUQ"},{"id":"yates-row","name":"Underhand Barbell Row (Yates)","group":"Back","primary":["Lats (lower)","Biceps"],"secondary":["Upper back"],"equip":"Barbell","tip":"Underhand, more upright than a normal row, pull to the belly.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/yates-row-0.jpg","img/yates-row-1.jpg"],"steps":["Stand holding a barbell with an underhand grip (palms facing forward), hands about shoulder width apart.","Bend your knees a little and lean forward only part of the way, roughly halfway between standing straight and flat. Keep your back straight and your chest up. This more upright position is what makes it a Yates row.","Pull the bar to your lower belly, keeping your elbows close to your sides. Squeeze your back for a moment at the top.","Lower the bar under control until your arms are straight.","Keep your torso still on every rep; do not swing the weight up."],"video":"ZdOS_zNafwo"},{"id":"pendlay-row","name":"Pendlay Row","group":"Back","primary":["Upper back"],"secondary":["Lats","Rear delts","Lower back"],"equip":"Barbell","tip":"Back parallel to the floor; bar rests on the floor between every rep, then explode up.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/pendlay-row-0.jpg","img/pendlay-row-1.jpg"],"steps":["Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.","Then inhale and slowly lower the barbell back to the starting position.","Repeat for the recommended amount of repetitions."],"video":"Wv7f0uIKh8o"},{"id":"one-arm-db-row","name":"One-Arm Dumbbell Row","group":"Back","primary":["Lats","Mid back"],"secondary":["Biceps","Rear delts"],"equip":"Dumbbell","tip":"Hand and knee on the bench, pull the elbow to the hip, not out to the side.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/one-arm-db-row-0.jpg","img/one-arm-db-row-1.jpg"],"steps":["Choose a flat bench and place a dumbbell on each side of it.","Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.","Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.","Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.","Lower the resistance straight down to the starting position. Breathe in as you perform this step.","Repeat the movement for the specified amount of repetitions."],"video":"vbechsUCn24"},{"id":"chest-supported-row","name":"Chest-Supported Row","group":"Back","primary":["Mid back","Upper back"],"secondary":["Lats","Rear delts","Biceps"],"equip":"Dumbbell","tip":"Chest on an incline bench (or the machine) — zero lower-back strain.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/chest-supported-row-0.jpg","img/chest-supported-row-1.jpg"],"steps":["Using a neutral grip, lean into an incline bench.","Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.","Retract the shoulder blades and flex the elbows to row the dumbbells to your side.","Pause at the top of the motion, and then return to the starting position."],"video":"h2Xafysr43E"},{"id":"t-bar-row","name":"T-Bar Row","group":"Back","primary":["Mid back","Lats"],"secondary":["Biceps","Rear delts","Lower back"],"equip":"Barbell","tip":"Chest up, pull the handle to the chest and squeeze the shoulder blades.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/t-bar-row-0.jpg","img/t-bar-row-1.jpg"],"steps":["Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.","Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position.","Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position.","Pull the weight to your upper abdomen by retracting the shoulder blades and flexing the elbows. Do not jerk the weight or cheat during the movement.","After a brief pause, return to the starting position."],"video":"oa-WYYfTYcM"},{"id":"machine-row","name":"Machine Row (plate-loaded)","group":"Back","primary":["Lats","Mid back"],"secondary":["Biceps","Rear delts"],"equip":"Machine","tip":"Low handles = lats, high/wide handles = upper back.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/machine-row-0.jpg","img/machine-row-1.jpg"],"steps":["Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.","Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.","Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."],"video":"9ZZjoyYr-Oo"},{"id":"single-arm-cable-row","name":"Single-Arm Cable Row","group":"Back","primary":["Lats","Mid back"],"secondary":["Biceps"],"equip":"Cable","tip":"Rotate slightly at the stretch, pull the elbow to the hip.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/single-arm-cable-row-0.jpg","img/single-arm-cable-row-1.jpg"],"steps":["To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.","Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip.","With your arm extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lat as you hold the bar in front of you. The right arm can be kept by the waist. This is the starting position of the exercise.","Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it as you rotate the wrist, so that by the time your hand is by your abdominals it is in a neutral position (palms facing the torso). Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard.","Hold that contraction for a second and slowly go back to the original position while breathing in. Tip: Remember to rotate the wrist as you go back to the starting position so that the palms are facing down again.","Repeat for the recommended amount of repetitions and then perform the same movement with the right hand."],"video":"oDKu4Y-hQtA"},{"id":"smith-row","name":"Smith Machine Row","group":"Back","primary":["Upper back","Lats"],"secondary":["Biceps","Rear delts"],"equip":"Smith","tip":"Fixed path — hinge over and pull to the lower chest.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/smith-row-0.jpg","img/smith-row-1.jpg"],"steps":["Set the barbell attached to the smith machine to a height that is about 2 inches below your knees.","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up.","Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang directly in front of you as your arms hang extended perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"video":"ZFNLCpj8e-o"},{"id":"meadows-row","name":"Meadows Row (landmine)","group":"Back","primary":["Lats","Upper back"],"secondary":["Rear delts","Biceps"],"equip":"Barbell","tip":"Stand side-on to the bar end, overhand grip, elbow flares out as you row.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/meadows-row-0.jpg","img/meadows-row-1.jpg"],"steps":["Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.","Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.","Now grab the bar with one arm just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.","Pull the bar straight up with your elbow in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Do not allow for any swinging of the torso. Only the arm should move.","Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).","Repeat for the recommended amount of repetitions and switch arms."],"video":"G-jU1aPVhnY"},{"id":"inverted-row","name":"Inverted Row","group":"Back","primary":["Upper back"],"secondary":["Lats","Biceps","Core"],"equip":"Bodyweight","tip":"Bar in the Smith / rack at waist height, body straight, pull chest to bar.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/inverted-row-0.jpg","img/inverted-row-1.jpg"],"steps":["Position a bar in a rack to about waist height. You can also use a smith machine.","Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.","Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.","Pause at the top of the motion, and return yourself to the start position.","Repeat for the desired number of repetitions."]},{"id":"back-extension","name":"Back Extension (hyperextension)","group":"Back","primary":["Lower back"],"secondary":["Glutes","Hamstrings"],"equip":"Bodyweight","tip":"Pad just below the hips; go up to straight, not past it. Hold a plate to add weight.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/back-extension-0.jpg","img/back-extension-1.jpg"],"steps":["Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.","Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.","With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.","Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.","Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.","Repeat for the recommended amount of repetitions."]},{"id":"leg-extension","name":"Leg Extension","group":"Quads","primary":["Quads"],"secondary":[],"equip":"Machine","tip":"Pad on the ankles, back flat against the seat, pause at the top.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/leg-extension-0.jpg","img/leg-extension-1.jpg"],"steps":["For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.","Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.","Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.","Repeat for the recommended amount of times."],"video":"xAUvXdHu1sI"},{"id":"back-squat","name":"Barbell Back Squat","group":"Quads","primary":["Quads","Glutes"],"secondary":["Hamstrings","Lower back","Core"],"equip":"Barbell","tip":"High-bar = more quads, low-bar = more glutes/hips. Pause squat: 2 s at the bottom.","mine":true,"track":"weight","alt":["High-bar","Low-bar","Pause squat"],"aka":[],"img":["img/back-squat-0.jpg","img/back-squat-1.jpg"],"steps":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"video":"QLbMsabhBqY"},{"id":"front-squat","name":"Front Squat","group":"Quads","primary":["Quads"],"secondary":["Glutes","Upper back","Core"],"equip":"Barbell","tip":"Bar on the front delts, elbows high, stay upright.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/front-squat-0.jpg","img/front-squat-1.jpg"],"steps":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.","Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor mainly with the middle of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"video":"OafwrCoaQj0"},{"id":"box-squat","name":"Box Squat","group":"Quads","primary":["Quads","Glutes"],"secondary":["Hamstrings"],"equip":"Barbell","tip":"Sit back to the box, pause, drive up — teaches depth and hip drive.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/box-squat-0.jpg","img/box-squat-1.jpg"],"steps":["The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe."],"video":"fVOrkHf_54k"},{"id":"smith-squat","name":"Smith Machine Squat","group":"Quads","primary":["Quads"],"secondary":["Glutes"],"equip":"Smith","tip":"Feet slightly in front of the bar = more quads; feet under = more glutes.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/smith-squat-0.jpg","img/smith-squat-1.jpg"],"steps":["To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"video":"iAcRGCsG_PY"},{"id":"leg-press","name":"Leg Press","group":"Quads","primary":["Quads","Glutes"],"secondary":["Hamstrings"],"equip":"Machine","tip":"Feet low/narrow = quads; high/wide = glutes & hamstrings. Single-leg for imbalances.","mine":true,"track":"weight","alt":["Feet low = quads","Feet high = glutes/hams","Single-leg"],"aka":[],"img":["img/leg-press-0.jpg","img/leg-press-1.jpg"],"steps":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.","As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.","Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.","Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."],"video":"K5n2vg3oZa4"},{"id":"hack-squat","name":"Hack Squat Machine","group":"Quads","primary":["Quads"],"secondary":["Glutes"],"equip":"Machine","tip":"Feet low on the platform for quads; go deep.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/hack-squat-0.jpg","img/hack-squat-1.jpg"],"steps":["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.","Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.","Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).","Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position."]},{"id":"goblet-squat","name":"Goblet Squat","group":"Quads","primary":["Quads","Glutes"],"secondary":["Core"],"equip":"Dumbbell","tip":"Dumbbell held at the chest, elbows inside the knees at the bottom.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/goblet-squat-0.jpg","img/goblet-squat-1.jpg"],"steps":["Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.","Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.","At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions."]},{"id":"bulgarian-split-squat","name":"Bulgarian Split Squat","group":"Quads","primary":["Quads","Glutes"],"secondary":["Hamstrings","Adductors"],"equip":"Dumbbell","tip":"Rear foot on a bench; long stance = glutes, short stance = quads.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/bulgarian-split-squat-0.jpg","img/bulgarian-split-squat-1.jpg"],"steps":["Position yourself into a staggered stance with the rear foot elevated and front foot forward.","Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.","Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.","At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position."]},{"id":"walking-lunge","name":"Walking Lunges","group":"Quads","primary":["Quads","Glutes"],"secondary":["Hamstrings"],"equip":"Dumbbell","tip":"Long steps, knee tracks over the toes, torso upright.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/walking-lunge-0.jpg","img/walking-lunge-1.jpg"],"steps":["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.","Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.","Using mainly the heel of your foot, push up and go back to the starting position as you exhale.","Repeat the movement for the recommended amount of repetitions and then perform with the left leg."]},{"id":"step-up","name":"Step-Ups","group":"Quads","primary":["Quads","Glutes"],"secondary":["Hamstrings"],"equip":"Dumbbell","tip":"Knee-height box; drive through the heel of the top leg, don't push off the bottom foot.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/step-up-0.jpg","img/step-up-1.jpg"],"steps":["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).","Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.","Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.","Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg."]},{"id":"seated-leg-curl","name":"Seated Hamstring Curl","group":"Hamstrings","primary":["Hamstrings"],"secondary":["Calves"],"equip":"Machine","tip":"Thigh pad tight, full stretch at the top — the best hamstring machine.","mine":true,"track":"weight","alt":[],"aka":["Seated Leg Curl"],"img":["img/seated-leg-curl-0.jpg","img/seated-leg-curl-1.jpg"],"steps":["Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.","Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.","As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"video":"Z5pRnXaCjpM"},{"id":"lying-leg-curl","name":"Lying Hamstring Curl","group":"Hamstrings","primary":["Hamstrings"],"secondary":["Calves","Glutes"],"equip":"Machine","tip":"Face down; hips stay on the pad, curl the pad to your glutes.","mine":true,"track":"weight","alt":[],"aka":["Lying Leg Curl","Prone Leg Curl"],"img":["img/lying-leg-curl-0.jpg","img/lying-leg-curl-1.jpg"],"steps":["Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.","Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.","As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.","As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions."],"video":"SbSNUXPRkc8"},{"id":"standing-leg-curl","name":"Standing Single-Leg Hamstring Curl","group":"Hamstrings","primary":["Hamstrings"],"secondary":["Calves"],"equip":"Machine","tip":"One leg at a time, squeeze at the top.","mine":true,"track":"weight","alt":[],"aka":["Standing Leg Curl"],"img":["img/standing-leg-curl-0.jpg","img/standing-leg-curl-1.jpg"],"steps":["Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.","Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position.","As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second.","As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.","Perform the same exercise now for the left leg."],"video":"_jl4nBsp74w"},{"id":"romanian-deadlift","name":"Romanian Deadlift (RDL)","group":"Hamstrings","primary":["Hamstrings","Glutes"],"secondary":["Lower back","Grip"],"equip":"Barbell","tip":"Soft knees, push the hips back, bar slides down the thighs to mid-shin. Barbell or dumbbells.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/romanian-deadlift-0.jpg","img/romanian-deadlift-1.jpg"],"steps":["Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.","Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.","Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.","Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.","Repeat for the recommended amount of repetitions."],"video":"_oyxCn2iSjU"},{"id":"stiff-leg-deadlift","name":"Stiff-Leg Deadlift","group":"Hamstrings","primary":["Hamstrings"],"secondary":["Lower back","Glutes"],"equip":"Barbell","tip":"Legs nearly straight, bar goes lower than an RDL — deeper stretch.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/stiff-leg-deadlift-0.jpg","img/stiff-leg-deadlift-1.jpg"],"steps":["Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight.","Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.","Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Inhale as you perform this movement.","Start bringing your torso up straight again by extending your hips until you are back at the starting position. Exhale as you perform this movement.","Repeat for the recommended amount of repetitions."],"video":"yYB9e6ZWGTc"},{"id":"single-leg-rdl","name":"Single-Leg RDL","group":"Hamstrings","primary":["Hamstrings","Glutes"],"secondary":["Core","Balance"],"equip":"Dumbbell","tip":"Dumbbell in the opposite hand to the working leg; hips square.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/single-leg-rdl-0.jpg","img/single-leg-rdl-1.jpg"],"steps":["Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell.","Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance.","Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position."],"video":"Zfr6wizR8rs"},{"id":"smith-rdl","name":"Smith Machine RDL","group":"Hamstrings","primary":["Hamstrings","Glutes"],"secondary":["Lower back"],"equip":"Smith","tip":"Fixed path lets you focus on the hip hinge.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/smith-rdl-0.jpg","img/smith-rdl-1.jpg"],"steps":["To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.","Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.","Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement","Start bringing your torso up straight again as soon as you feel the hamstrings stretch by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.","Repeat for the recommended amount of repetitions."],"video":"Ghc9V73wTyQ"},{"id":"nordic-curl","name":"Nordic Curl","group":"Hamstrings","primary":["Hamstrings"],"secondary":["Glutes","Calves"],"equip":"Bodyweight","tip":"Ankles pinned, lower as slowly as you can, push back up with the hands.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/nordic-curl-0.jpg","img/nordic-curl-1.jpg"],"steps":["Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture.","This will be your starting position. Lower yourself under control until your knees are almost completely straight.","Remaining in control, raise yourself back up to the starting position.","If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition."]},{"id":"good-morning","name":"Good Morning","group":"Hamstrings","primary":["Hamstrings","Lower back"],"secondary":["Glutes"],"equip":"Barbell","tip":"Light bar on the back, hinge to ~parallel, soft knees.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/good-morning-0.jpg","img/good-morning-1.jpg"],"steps":["Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.","Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.","Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position."]},{"id":"conventional-deadlift","name":"Conventional Deadlift","group":"Glutes","primary":["Glutes","Hamstrings","Lower back"],"secondary":["Quads","Upper traps","Grip","Core"],"equip":"Barbell","tip":"Bar over mid-foot, hips above knees, push the floor away. Whole posterior chain.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/conventional-deadlift-0.jpg","img/conventional-deadlift-1.jpg"],"steps":["Stand in front of a loaded barbell.","While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.","While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.","Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.","Perform the amount of repetitions prescribed in the program."],"video":"l5Ckg1lwVgE"},{"id":"sumo-deadlift","name":"Sumo Deadlift","group":"Glutes","primary":["Glutes","Quads","Adductors"],"secondary":["Hamstrings","Lower back","Grip"],"equip":"Barbell","tip":"Wide stance, toes out, hands inside the knees — less lower back.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/sumo-deadlift-0.jpg","img/sumo-deadlift-1.jpg"],"steps":["Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.","Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.","As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."],"video":"e7oLkRlT2CQ"},{"id":"trap-bar-deadlift","name":"Trap-Bar (Hex-Bar) Deadlift","group":"Glutes","primary":["Quads","Glutes"],"secondary":["Hamstrings","Lower back","Grip"],"equip":"Barbell","tip":"Neutral handles, easiest deadlift on the back.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/trap-bar-deadlift-0.jpg","img/trap-bar-deadlift-1.jpg"],"steps":["For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles.","Lower your hips, look forward with your head and keep your chest up.","Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times.","At the completion of the movement, lower the weight back to the ground under control."],"video":"HdzmPAEE2C4"},{"id":"rack-pull","name":"Rack Pull","group":"Back","primary":["Upper back","Upper traps"],"secondary":["Glutes","Hamstrings","Grip"],"equip":"Barbell","tip":"Pins at or just below the knee; heavy lockout work.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/rack-pull-0.jpg","img/rack-pull-1.jpg"],"steps":["Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.","With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement.","Return the weight to the pins and repeat."],"video":"IZjW_8R9UYE"},{"id":"deficit-deadlift","name":"Deficit Deadlift","group":"Glutes","primary":["Glutes","Hamstrings","Quads"],"secondary":["Lower back"],"equip":"Barbell","tip":"Stand on a plate or small platform — extra range off the floor.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/deficit-deadlift-0.jpg","img/deficit-deadlift-1.jpg"],"steps":["Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.","With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."],"video":"quH1dGSOudA"},{"id":"hip-thrust","name":"Hip Thrust","group":"Glutes","primary":["Glutes"],"secondary":["Hamstrings"],"equip":"Barbell","tip":"Upper back on a bench, chin tucked, squeeze hard at the top. Barbell or machine.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/hip-thrust-0.jpg","img/hip-thrust-1.jpg"],"steps":["Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.","Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.","Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position."]},{"id":"glute-kickback","name":"Cable Glute Kickback","group":"Glutes","primary":["Glutes"],"secondary":["Hamstrings"],"equip":"Cable","tip":"Ankle strap on the low pulley, kick back and slightly up, no arching.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/glute-kickback-0.jpg","img/glute-kickback-1.jpg"],"steps":["Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.","Face the weight stack from a distance of about two feet, grasping the steel frame for support.","While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly \"kick\" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.","Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.","Repeat for the recommended amount of repetitions.","Switch legs and repeat the movement for the other side."]},{"id":"hip-abduction","name":"Hip Abduction Machine","group":"Glutes","primary":["Glutes (side)","Abductors"],"secondary":[],"equip":"Machine","tip":"Lean forward slightly for more glute; pause at the widest point.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/hip-abduction-0.jpg","img/hip-abduction-1.jpg"],"steps":["To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.","Slowly press against the machine with your legs to move them away from each other while exhaling.","Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.","Repeat for the recommended amount of repetitions."]},{"id":"hip-adduction","name":"Hip Adduction Machine","group":"Glutes","primary":["Adductors (inner thigh)"],"secondary":[],"equip":"Machine","tip":"Control the opening, squeeze on the way in.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/hip-adduction-0.jpg","img/hip-adduction-1.jpg"],"steps":["To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.","Slowly press against the machine with your legs to move them towards each other while exhaling.","Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.","Repeat for the recommended amount of repetitions."]},{"id":"standing-calf-raise","name":"Standing Calf Raise","group":"Calves","primary":["Calves (gastrocnemius)"],"secondary":["Calves (soleus)"],"equip":"Machine","tip":"Machine or Smith. Full stretch at the bottom, 1-s pause at the top.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/standing-calf-raise-0.jpg","img/standing-calf-raise-1.jpg"],"steps":["Adjust the padded lever of the calf raise machine to fit your height.","Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"video":"4HQ8Am9IuME"},{"id":"seated-calf-raise","name":"Seated Calf Raise","group":"Calves","primary":["Calves (soleus)"],"secondary":[],"equip":"Machine","tip":"Knee bent = soleus, the deep lower calf. Slow reps.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/seated-calf-raise-0.jpg","img/seated-calf-raise-1.jpg"],"steps":["Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.","Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.","Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.","Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.","Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.","Repeat for the recommended amount of repetitions."],"video":"6O5hh1rBtx8"},{"id":"leg-press-calf-raise","name":"Leg Press Calf Raise","group":"Calves","primary":["Calves (gastrocnemius)"],"secondary":[],"equip":"Machine","tip":"Toes on the bottom edge of the platform, knees straight.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/leg-press-calf-raise-0.jpg","img/leg-press-calf-raise-1.jpg"],"steps":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.","Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"video":"2w__B-cI6kQ"},{"id":"single-leg-calf-raise","name":"Single-Leg Dumbbell Calf Raise","group":"Calves","primary":["Calves (gastrocnemius)"],"secondary":["Balance"],"equip":"Dumbbell","tip":"On a step, dumbbell on the working side, hold something for balance.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/single-leg-calf-raise-0.jpg","img/single-leg-calf-raise-1.jpg"],"steps":["Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position.","With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top contraction for a second.","As you inhale, go back to the starting position by slowly lowering the heels.","Repeat for the recommended amount of times."],"video":"wdeoWVddAGY"},{"id":"donkey-calf-raise","name":"Donkey Calf Raise","group":"Calves","primary":["Calves (gastrocnemius)"],"secondary":[],"equip":"Machine","tip":"Hips bent, the gastroc is stretched — great if your gym has the machine.","mine":true,"track":"weight","alt":[],"aka":[],"img":["img/donkey-calf-raise-0.jpg","img/donkey-calf-raise-1.jpg"],"steps":["For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.","Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"video":"EQyCroWhIPs"},{"id":"hanging-leg-raise","name":"Hanging Leg / Knee Raise","group":"Core","primary":["Abs (lower)","Hip flexors"],"secondary":["Grip","Obliques"],"equip":"Bodyweight","tip":"Knees bent is easier; curl the pelvis up at the top, don't just swing the legs.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/hanging-leg-raise-0.jpg","img/hanging-leg-raise-1.jpg"],"steps":["Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.","Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.","Go back slowly to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."]},{"id":"cable-crunch","name":"Cable Crunch","group":"Core","primary":["Abs"],"secondary":["Obliques"],"equip":"Cable","tip":"Kneel, rope behind the head, crunch the ribs toward the hips — hips stay still.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/cable-crunch-0.jpg","img/cable-crunch-1.jpg"],"steps":["Kneel below a high pulley that contains a rope attachment.","Grasp cable rope attachment and lower the rope until your hands are placed next to your face.","Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.","With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.","Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.","Repeat for the recommended amount of repetitions."]},{"id":"plank","name":"Plank","group":"Core","primary":["Abs","Core"],"secondary":["Glutes","Shoulders"],"equip":"Bodyweight","tip":"Squeeze glutes, tuck the pelvis, breathe. Time it.","mine":false,"track":"time","alt":[],"aka":[],"img":["img/plank-0.jpg","img/plank-1.jpg"],"steps":["Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.","Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised."]},{"id":"ab-wheel","name":"Ab Wheel Rollout","group":"Core","primary":["Abs"],"secondary":["Lats","Hip flexors"],"equip":"Other","tip":"From the knees; roll out only as far as you can keep the lower back flat.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/ab-wheel-0.jpg","img/ab-wheel-1.jpg"],"steps":["Hold the Ab Roller with both hands and kneel on the floor.","Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.","Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.","After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times."]},{"id":"decline-situp","name":"Decline Sit-Up","group":"Core","primary":["Abs","Hip flexors"],"secondary":[],"equip":"Bodyweight","tip":"Hold a plate on the chest to add weight; control the way down.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/decline-situp-0.jpg","img/decline-situp-1.jpg"],"steps":["Secure your legs at the end of the decline bench and lie down.","Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.","While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.","Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don't cheat yourself by using momentum.","After the one second contraction, begin to come down slowly again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]},{"id":"machine-crunch","name":"Machine Crunch","group":"Core","primary":["Abs"],"secondary":[],"equip":"Machine","tip":"Crunch the ribs down, pause, slow return.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/machine-crunch-0.jpg","img/machine-crunch-1.jpg"],"steps":["Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.","At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.","After a second pause, slowly return to the starting position as you breathe in.","Repeat the movement for the prescribed amount of repetitions."]},{"id":"russian-twist","name":"Russian Twist","group":"Core","primary":["Obliques"],"secondary":["Abs"],"equip":"Other","tip":"Feet off the floor, rotate the chest, not just the arms. Plate or dumbbell.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/russian-twist-0.jpg","img/russian-twist-1.jpg"],"steps":["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.","Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.","Twist your torso to the right side until your arms are parallel with the floor while breathing out.","Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.","Repeat for the recommended amount of repetitions."]},{"id":"crunch","name":"Crunch","group":"Core","primary":["Upper abs"],"secondary":[],"equip":"Bodyweight","tip":"Lift only the shoulder blades; ribs toward the hips, a fist of space under the chin.","mine":false,"track":"bw","alt":[],"aka":["Crunches","Basic crunch"],"img":["img/crunch-0.jpg","img/crunch-1.jpg"],"steps":["Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.","Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.","While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.","Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don't cheat yourself by using momentum.","After the one second contraction, begin to come down slowly again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]},{"id":"crunch-hands-overhead","name":"Crunch (hands overhead)","group":"Core","primary":["Upper abs"],"secondary":[],"equip":"Bodyweight","tip":"Arms stay by your ears the whole time: a longer lever, so harder than hands by the head.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/crunch-hands-overhead-0.jpg","img/crunch-hands-overhead-1.jpg"],"steps":["Lie on the floor with your back flat and knees bent with around a 60-degree angle between the hamstrings and the calves.","Keep your feet flat on the floor and stretch your arms overhead with your palms crossed. This will be your starting position.","Curl your upper body forward and bring your shoulder blades just off the floor. At all times, keep your arms aligned with your head, neck and shoulder. Don't move them forward from that position. Exhale as you perform this portion of the movement and hold the contraction for a second.","Slowly lower down to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]},{"id":"crunch-legs-on-ball","name":"Crunch (legs on a ball)","group":"Core","primary":["Upper abs"],"secondary":["Hip flexors"],"equip":"Other","tip":"Calves on the ball, knees at 90°; curl the ribs up without pulling on your head.","mine":false,"track":"bw","alt":[],"aka":["Swiss ball crunch"],"img":["img/crunch-legs-on-ball-0.jpg","img/crunch-legs-on-ball-1.jpg"],"steps":["Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle.","Place your feet three to four inches apart and point your toes inward so they touch.","Place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.","Push the small of your back down in the floor in order to better isolate your abdominal muscles. This will be your starting position.","Begin to roll your shoulders off the floor and continue to push down as hard as you can with your lower back. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. Breathe out as you execute this portion of the movement. Squeeze your abdominals hard at the top of the contraction and hold for a second. Tip: Focus on a slow, controlled movement. Refrain from using momentum at any time.","Slowly go back down to the starting position as you inhale."]},{"id":"cross-body-crunch","name":"Cross-Body Crunch","group":"Core","primary":["Obliques","Upper abs"],"secondary":[],"equip":"Bodyweight","tip":"Bring the elbow toward the opposite knee; twist from the ribs, not the neck.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/cross-body-crunch-0.jpg","img/cross-body-crunch-1.jpg"],"steps":["Lie flat on your back and bend your knees about 60 degrees.","Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position.","Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement. Tip: Try to bring your shoulder up towards your knee rather than just your elbow and remember that the key is to contract the abs as you perform the movement; not just to move the elbow.","Now go back down to the starting position as you inhale and repeat with the left elbow and the right knee.","Continue alternating in this manner until all prescribed repetitions are done."]},{"id":"bicycle-crunch","name":"Bicycle Crunch","group":"Core","primary":["Obliques","Abs"],"secondary":["Hip flexors"],"equip":"Bodyweight","tip":"Go slow: turn until the shoulder (not just the elbow) crosses, other leg straight and low.","mine":false,"track":"bw","alt":[],"aka":["Air bike","Bicycles"],"img":["img/bicycle-crunch-0.jpg","img/bicycle-crunch-1.jpg"],"steps":["Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.","Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.","Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.","Go back to the initial position as you breathe in.","Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.","Continue alternating in this manner until all of the recommended repetitions for each side have been completed."]},{"id":"oblique-crunch","name":"Oblique Crunch","group":"Core","primary":["Obliques"],"secondary":["Upper abs"],"equip":"Bodyweight","tip":"Crunch up and across to one side; lower back stays on the floor.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/oblique-crunch-0.jpg","img/oblique-crunch-1.jpg"],"steps":["Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against the floor.","Make sure your feet are elevated and resting on a flat surface.","Now lift the shoulder in which your hand is touching your head.","Simply elevate your shoulder and body upward until you touch your knee. For example, if you have your right hand besides your head, then you want to elevate your body upwards until your right elbow touches your left knee. The same variation can be applied doing the inverse and using your left elbow to touch your right knee.","After your knee touches your elbow, lower your body until you have reached the starting position.","Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (upward) part of the exercise."]},{"id":"side-lying-oblique-crunch","name":"Side-Lying Oblique Crunch","group":"Core","primary":["Obliques"],"secondary":[],"equip":"Bodyweight","tip":"Lie on your side, knees bent; lift the shoulder toward the hip, small and slow.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/side-lying-oblique-crunch-0.jpg","img/side-lying-oblique-crunch-1.jpg"],"steps":["Start out by lying on your right side with your legs lying on top of each other. Make sure your knees are bent a little bit.","Place your left hand behind your head.","Once you are in this set position, begin by moving your left elbow up as you would perform a normal crunch except this time the main emphasis is on your obliques.","Crunch as high as you can, hold the contraction for a second and then slowly drop back down into the starting position.","Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (elevation) part of the exercise."]},{"id":"decline-oblique-crunch","name":"Decline Oblique Crunch","group":"Core","primary":["Obliques"],"secondary":["Upper abs"],"equip":"Bodyweight","tip":"Twist as you come up, elbow toward the opposite knee; lower slowly.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/decline-oblique-crunch-0.jpg","img/decline-oblique-crunch-1.jpg"],"steps":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor.","Put one hand beside your head and the other on your thigh. This will be your starting position.","Raise your upper body slowly from the starting position while turning your torso to the left. Continue crunching up as you exhale until your right elbow touches your left knee. Hold this contracted position for a second. Tip: Focus on keeping your abs tight and keeping the movement slow and controlled.","Lower your body back down slowly to the starting position as you inhale.","After completing one set on the right for the recommended amount of repetitions, switch to your left side. Tip: Focus on really twisting your torso and feeling the contraction when you are in the up position."]},{"id":"tuck-crunch","name":"Tuck Crunch","group":"Core","primary":["Upper abs","Lower abs"],"secondary":[],"equip":"Bodyweight","tip":"Thighs straight up, ankles crossed; curl the shoulders toward the knees.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/tuck-crunch-0.jpg","img/tuck-crunch-1.jpg"],"steps":["To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.","Your legs should be crossed by wrapping one ankle around the other. Slowly elevate your legs up in the air until your thighs are perpendicular to the floor with a slight bend at the knees. Note: Your knees and toes should be parallel to the floor as opposed to the thighs.","Move your arms from the floor and cross them so they are resting on your chest. This is the starting position.","While keeping your lower back pressed against the floor, slowly lift your torso. Remember to exhale while perform this part of the exercise.","Slowly begin to lower your torso back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."]},{"id":"elbow-to-knee","name":"Elbow-to-Knee Crunch","group":"Core","primary":["Obliques"],"secondary":["Upper abs"],"equip":"Bodyweight","tip":"One ankle on the other knee; bring the opposite elbow to it, then switch sides.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/elbow-to-knee-0.jpg","img/elbow-to-knee-1.jpg"],"steps":["Lie on the floor, crossing your right leg across your bent left knee. Clasp your hands behind your head, beginning with your shoulder blades on the ground. This will be your starting position.","Perform the motion by flexing the spine and rotating your torso to bring the left elbow to the right knee.","Return to the starting position and repeat the movement for the desired number of repetitions before switching sides."]},{"id":"heel-taps","name":"Heel Taps","group":"Core","primary":["Obliques"],"secondary":[],"equip":"Bodyweight","tip":"Shoulders stay off the floor the whole set; bend to the side to tap each heel.","mine":false,"track":"bw","alt":[],"aka":["Heel touches","Alternate heel touchers"],"img":["img/heel-taps-0.jpg","img/heel-taps-1.jpg"],"steps":["Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.","Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.","Now go back slowly to the starting position as you inhale.","Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.","Continue alternating sides in this manner until all prescribed repetitions are done."]},{"id":"ball-crunch","name":"Exercise Ball Crunch","group":"Core","primary":["Upper abs"],"secondary":[],"equip":"Other","tip":"Ball under the lower back; stretch back over it, then curl up: more range than on the floor.","mine":false,"track":"bw","alt":[],"aka":["Swiss ball crunch","Stability ball crunch"],"img":["img/ball-crunch-0.jpg","img/ball-crunch-1.jpg"],"steps":["Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head position).","Lower your torso into a stretch position keeping the neck stationary at all times. This will be your starting position.","With the hips stationary, flex the waist by contracting the abdominals and curl the shoulders and trunk upward until you feel a nice contraction on your abdominals. The arms should simply slide up the side of your legs if you have them at the side or just stay on top of your chest if you have them crossed. The lower back should always stay in contact with the ball. Exhale as you perform this movement and hold the contraction for a second.","As you inhale, go back to the starting position.","Repeat for the recommended amount of repetitions."]},{"id":"weighted-crunch","name":"Weighted Crunch","group":"Core","primary":["Upper abs"],"secondary":[],"equip":"Other","tip":"Plate or medicine ball on the chest (harder held overhead); add weight once 15 clean reps are easy.","mine":false,"track":"weight","alt":[],"aka":["Plate crunch","Medicine ball crunch"],"img":["img/weighted-crunch-0.jpg","img/weighted-crunch-1.jpg"],"steps":["Lie flat on your back with your feet flat on the ground or resting on a bench with your knees bent at a 90 degree angle.","Hold a weight to your chest, or you may hold it extended above your torso. This will be your starting position.","Now, exhale and slowly begin to roll your shoulders off the floor. Your shoulders should come up off the floor about 4 inches while your lower back remains on the floor.","At the top of the movement, flex your abdominals and hold for a brief pause.","Then inhale and slowly lower yourself back down to the starting position."]},{"id":"toe-touches","name":"Toe Touches","group":"Core","primary":["Upper abs"],"secondary":[],"equip":"Bodyweight","tip":"Legs straight up; reach for the toes by lifting the shoulder blades, not by swinging the arms.","mine":false,"track":"bw","alt":[],"aka":["Toe touchers","Toe reaches"],"img":["img/toe-touches-0.jpg","img/toe-touches-1.jpg"],"steps":["To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.","Your legs should be touching each other. Slowly elevate your legs up in the air until they are almost perpendicular to the floor with a slight bend at the knees. Your feet should be parallel to the floor.","Move your arms so that they are fully extended at a 45 degree angle from the floor. This is the starting position.","While keeping your lower back pressed against the floor, slowly lift your torso and use your hands to try and touch your toes. Remember to exhale while perform this part of the exercise.","Slowly begin to lower your torso and arms back down to the starting position while inhaling. Remember to keep your arms straight out pointing towards your toes.","Repeat for the recommended amount of repetitions."]},{"id":"cocoons","name":"Cocoons","group":"Core","primary":["Abs"],"secondary":["Hip flexors"],"equip":"Bodyweight","tip":"Knees in and arms over to meet them, then stretch out long without touching down.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/cocoons-0.jpg","img/cocoons-1.jpg"],"steps":["Begin by lying on your back on the ground. Your legs should be straight and your arms extended behind your head. This will be your starting position.","To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor. As you do so, flex the spine, bringing your arms back over your head to perform a simultaneous crunch motion.","After a brief pause, return to the starting position."]},{"id":"side-jackknife","name":"Side Jackknife","group":"Core","primary":["Obliques"],"secondary":[],"equip":"Bodyweight","tip":"On your side; lift the top leg and the upper body together, squeeze, lower slowly.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/side-jackknife-0.jpg","img/side-jackknife-1.jpg"],"steps":["Lie on your side with your legs straight and stacked, the bottom arm on the floor in front of you for balance.","Put your top hand behind your head.","Lift your top leg and your upper body at the same time, bringing the elbow toward the knee.","Squeeze the side of your waist, lower slowly, and do the other side after the set."]},{"id":"rope-crunch","name":"Rope Crunch (arms overhead)","group":"Core","primary":["Abs"],"secondary":[],"equip":"Cable","tip":"Kneel facing the stack, rope overhead; pull the ribs to the hips, hips stay still.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/rope-crunch-0.jpg","img/rope-crunch-1.jpg"],"steps":["Kneel 1-2 feet in front of a cable system with a rope attached.","After selecting an appropriate weight, grasp the rope with both hands reaching overhead. Your torso should be upright in the starting position.","To begin, flex at the spine, attempting to bring your rib cage to your legs as you pull the cable down.","Pause at the bottom of the motion, and then slowly return to the starting position.","These can be done with twists or to the side to hit the obliques."]},{"id":"standing-cable-crunch","name":"Standing Cable Crunch","group":"Core","primary":["Abs"],"secondary":[],"equip":"Cable","tip":"Back to the stack, rope on the upper chest; crunch down and hold a second.","mine":false,"track":"weight","alt":[],"aka":["Standing rope crunch"],"img":["img/standing-cable-crunch-0.jpg","img/standing-cable-crunch-1.jpg"],"steps":["Attach a rope to a high pulley and select an appropriate weight.","Stand with your back to the cable tower. Take the rope with both hands over your shoulders, holding it to your upper chest. This will be your starting position.","Perform the movement by flexing the spine, crunching the weight down as far as you can.","Hold the peak contraction for a moment before returning to the starting position."]},{"id":"seated-cable-crunch","name":"Seated Cable Crunch","group":"Core","primary":["Abs"],"secondary":[],"equip":"Cable","tip":"Sit with your back to a high pulley, rope over the shoulders; crunch down, hips still.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/seated-cable-crunch-0.jpg","img/seated-cable-crunch-1.jpg"],"steps":["Seat on a flat bench with your back facing a high pulley.","Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position.","With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this step.","As you inhale, go back to the initial position slowly.","Repeat for the recommended amount of repetitions."]},{"id":"cable-crunch-twist","name":"Kneeling Cable Crunch with Twist","group":"Core","primary":["Obliques","Abs"],"secondary":[],"equip":"Cable","tip":"Crunch down and turn the elbows toward one knee, then the other.","mine":false,"track":"weight","alt":[],"aka":["Oblique cable crunch"],"img":["img/cable-crunch-twist-0.jpg","img/cable-crunch-twist-1.jpg"],"steps":["Connect a rope attachment to a high pulley cable and position a mat on the floor in front of it.","Grab the rope with both hands and kneel approximately two feet back from the tower.","Position the rope behind your head with your hands by your ears.","Keep your hands in the same place, contract your abs and pull downward on the rope in a crunching movement until your elbows reach your knees.","Pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.","Repeat the same downward movement until you're halfway down, at which time you'll begin rotating one of your elbows to the opposite knee."]},{"id":"bosu-cable-crunch","name":"BOSU Cable Crunch with Side Bends","group":"Core","primary":["Abs","Obliques"],"secondary":[],"equip":"Cable","tip":"Lower back over the BOSU; crunch up, then bend to each side under control.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/bosu-cable-crunch-0.jpg","img/bosu-cable-crunch-1.jpg"],"steps":["Connect a standard handle to each arm of a cable machine, and position them in the most downward position.","Grab a Bosu Ball and position it in front and center of the cable machine.","Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it.","With both hands, reach back and grab the handle of each cable.","With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees. Your hands should be at knee level.","Keep your arms straight and in-line with the upward angle of the cable. Elevate your torso in a crunching motion without dropping or bending your arms."],"x":1},{"id":"cable-reverse-crunch","name":"Cable Reverse Crunch","group":"Core","primary":["Lower abs"],"secondary":["Hip flexors"],"equip":"Cable","tip":"Ankle straps on a low pulley; curl the hips up toward the ribs, not just the knees in.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/cable-reverse-crunch-0.jpg","img/cable-reverse-crunch-1.jpg"],"steps":["Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it.","Sit down with your feet toward the pulley and attach the cable to your ankles.","Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are.","With your hands behind your head, bring your knees inward to your torso and elevate your hips off the floor.","Pause for a moment and in a slow and controlled manner drop your hips and bring your legs back to the starting 90-degree angle. You should still have tension on your abs in the resting position.","Repeat the same movement to failure."]},{"id":"cable-side-bend","name":"High-Pulley Cable Side Bend","group":"Core","primary":["Obliques"],"secondary":[],"equip":"Cable","tip":"Elbow pinned to your side; bend straight down to the side, no twisting.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/cable-side-bend-0.jpg","img/cable-side-bend-1.jpg"],"steps":["Connect a standard handle to a tower. Move cable to highest pulley position.","Stand with side to cable. With one hand, reach up and grab handle with underhand grip.","Pull down cable until elbow touches your side and the handle is by your shoulder.","Position feet hip-width apart. Place free hand on hip to help gauge pivot point.","Keep arm in static position. Contract oblique to bring the weight down in a side crunch.","Once you reach maximum contraction, slowly release the weight to the starting position. The weight stack should never be unloaded in a resting position. The aim is constant tension during the set."]},{"id":"cable-russian-twist","name":"Cable Russian Twist","group":"Core","primary":["Obliques"],"secondary":["Abs"],"equip":"Cable","tip":"On a ball side-on to the cable, arms straight; turn the chest away from the stack.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/cable-russian-twist-0.jpg","img/cable-russian-twist-1.jpg"],"steps":["Connect a standard handle attachment, and position the cable to a middle pulley position.","Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable.","Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are.","Keep your hips elevated and abs engaged. Rotate your torso away from the pulley for a full-quarter rotation. Your body should be flat from head to knees.","Pause for a moment and in a slow and controlled manner reset to the starting position. You should still have side tension on the cable in the resting position.","Repeat the same movement to failure."]},{"id":"cable-woodchop","name":"Cable Woodchop (high to low)","group":"Core","primary":["Obliques"],"secondary":["Abs","Shoulders"],"equip":"Cable","tip":"Arms long, turn from the hips and ribs; let the back foot pivot.","mine":false,"track":"weight","alt":[],"aka":["Wood chop","Woodchopper","Cable chop"],"img":["img/cable-woodchop-0.jpg","img/cable-woodchop-1.jpg"],"steps":["Connect a standard handle to a tower, and move the cable to the highest pulley position.","With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.","With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.","In one motion, pull the handle down and across your body to your front knee while rotating your torso.","Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.","Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner."]},{"id":"cable-lift","name":"Cable Lift (low to high woodchop)","group":"Core","primary":["Obliques"],"secondary":["Shoulders"],"equip":"Cable","tip":"Low pulley; lift up and across the body, turning the chest, arms long.","mine":false,"track":"weight","alt":[],"aka":["Reverse woodchop"],"img":["img/cable-lift-0.jpg","img/cable-lift-1.jpg"],"steps":["Connect a standard handle on a tower, and move the cable to the lowest pulley position.","With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.","With your feet positioned shoulder width apart, squat down and grab the handle with both hands. Your arms should still be fully extended.","In one motion, pull the handle up and across your body until your arms are in a fully-extended position above your head.","Keep your back straight and your arms close to your body as you pivot your back foot and straighten your legs to get a full range of motion.","Retract your arms and then your body. Return to the neutral position in a slow and controlled manner."]},{"id":"cable-judo-flip","name":"Cable Judo Flip","group":"Core","primary":["Obliques"],"secondary":["Abs","Shoulders"],"equip":"Cable","tip":"Rope on a low pulley; pull it over the far shoulder as you turn away and shift your weight.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/cable-judo-flip-0.jpg","img/cable-judo-flip-1.jpg"],"steps":["Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Stand with your side to the cable with a wide stance, and grab the rope with both hands.","Twist your body away from the pulley as you bring the rope over your shoulder like you're performing a judo flip.","Shift your weight between your feet as you twist and crunch forward, pulling the cable downward.","Return to the starting position and repeat until failure.","Then, reposition and repeat the same series of movements on the opposite side."]},{"id":"pallof-press","name":"Pallof Press","group":"Core","primary":["Obliques","Core"],"secondary":["Shoulders"],"equip":"Cable","tip":"Press straight out and don't let the cable turn you: resisting the twist is the exercise.","mine":false,"track":"weight","alt":[],"aka":["Anti-rotation press"],"img":["img/pallof-press-0.jpg","img/pallof-press-1.jpg"],"steps":["Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.","With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable.","With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.","Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.","Hold the repetition for several seconds before returning to the starting position.","At the conclusion of the set, repeat facing the other direction."]},{"id":"pallof-press-rotation","name":"Pallof Press with Rotation","group":"Core","primary":["Obliques","Core"],"secondary":["Shoulders"],"equip":"Cable","tip":"Press out, turn the arms away from the stack under control, come back, then bring them in.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/pallof-press-rotation-0.jpg","img/pallof-press-rotation-1.jpg"],"steps":["Connect a standard handle to a tower, and position the cable to shoulder height.","With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable.","With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time.","Facing forward, press the cable away from your chest. You core should be tight and engaged.","Keeping your hips straight, twist your torso away from the pulley until you get a full quarter rotation.","Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. Your arms should be extended in front of you."]},{"id":"reverse-crunch","name":"Reverse Crunch","group":"Core","primary":["Lower abs"],"secondary":["Hip flexors"],"equip":"Bodyweight","tip":"Curl the hips off the floor toward the ribs; no swinging, lower slowly.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/reverse-crunch-0.jpg","img/reverse-crunch-1.jpg"],"steps":["Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.","Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.","While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.","Hold the contraction for a second and move your legs back to the starting position while exhaling.","Repeat for the recommended amount of repetitions."]},{"id":"decline-reverse-crunch","name":"Decline Reverse Crunch","group":"Core","primary":["Lower abs"],"secondary":["Hip flexors"],"equip":"Bodyweight","tip":"Hold the top of the bench; lift the hips up off the bench, not only the legs.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/decline-reverse-crunch-0.jpg","img/decline-reverse-crunch-1.jpg"],"steps":["Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don't let your body slip down from this position.","Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position.","While exhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the bench. At the end of this movement your knees will be touching your chest.","Hold the contraction for a second and move your legs back to the starting position while inhaling.","Repeat for the recommended amount of repetitions."]},{"id":"lying-leg-raise","name":"Lying Leg Raise","group":"Core","primary":["Lower abs","Hip flexors"],"secondary":[],"equip":"Bodyweight","tip":"On a bench or the floor; lower back stays pressed down, so lower only as far as it can stay there.","mine":false,"track":"bw","alt":[],"aka":["Leg raises","Flat bench leg raise"],"img":["img/lying-leg-raise-0.jpg","img/lying-leg-raise-1.jpg"],"steps":["Lie with your back flat on a bench and your legs extended in front of you off the end.","Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position.","As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second.","Now, as you inhale, slowly lower your legs back down to the starting position."]},{"id":"lying-knee-tuck","name":"Lying Knee Tuck","group":"Core","primary":["Lower abs"],"secondary":["Hip flexors"],"equip":"Bodyweight","tip":"Pull the knees to your chest and roll the hips up a little; straighten slowly.","mine":false,"track":"bw","alt":[],"aka":["Leg pull-in"],"img":["img/lying-knee-tuck-0.jpg","img/lying-knee-tuck-1.jpg"],"steps":["Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position.","Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should always remain parallel to the floor.","Return to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]},{"id":"bench-knee-tuck","name":"Bench Knee Tuck","group":"Core","primary":["Lower abs"],"secondary":["Hip flexors"],"equip":"Bodyweight","tip":"Lying on a bench with the legs off the end; knees in, then out until just above the floor.","mine":false,"track":"bw","alt":[],"aka":["Bench leg pull-in"],"img":["img/bench-knee-tuck-0.jpg","img/bench-knee-tuck-1.jpg"],"steps":["Lie on an exercise mat or a flat bench with your legs off the end.","Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position.","Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue this movement until your knees are near your chest. Hold the contracted position for a second.","As you breathe in, slowly return to the starting position.","Repeat for the recommended amount of repetitions."]},{"id":"seated-knee-tuck","name":"Seated Knee Tuck","group":"Core","primary":["Lower abs"],"secondary":["Hip flexors"],"equip":"Bodyweight","tip":"Lean back on your hands; bring knees and chest together, then stretch out without touching down.","mine":false,"track":"bw","alt":[],"aka":["Seated in and outs","Seated leg tucks"],"img":["img/seated-knee-tuck-0.jpg","img/seated-knee-tuck-1.jpg"],"steps":["Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.","Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.","After a second pause, go back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]},{"id":"bent-knee-hip-raise","name":"Bent-Knee Hip Raise","group":"Core","primary":["Lower abs"],"secondary":[],"equip":"Bodyweight","tip":"Knees bent and feet just off the floor; use the lower abs to lift the hips, small and slow.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/bent-knee-hip-raise-0.jpg","img/bent-knee-hip-raise-1.jpg"],"steps":["Lay flat on the floor with your arms next to your sides.","Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches.","Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs. Continue this movement until you raise your hips off of the floor by rolling your pelvis backward. Breathe out as you perform this portion of the movement. Tip: At the end of the movement your knees will be over your chest.","Squeeze your abs at the top of the movement for a second and then return to the starting position slowly as you breathe in. Tip: Maintain a controlled motion at all times.","Repeat for the recommended amount of repetitions."]},{"id":"bottoms-up","name":"Bottoms Up","group":"Core","primary":["Lower abs"],"secondary":["Hip flexors"],"equip":"Bodyweight","tip":"Knees in, legs straight up, then lift the hips toward the ceiling; lower one part at a time.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/bottoms-up-0.jpg","img/bottoms-up-1.jpg"],"steps":["Begin by lying on your back on the ground. Your legs should be straight and your arms at your side. This will be your starting position.","To perform the movement, tuck the knees toward your chest by flexing the hips and knees. Following this, extend your legs directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your glutes from the floor.","After a brief pause, return to the starting position."]},{"id":"smith-hip-raise","name":"Smith Machine Hip Raise","group":"Core","primary":["Lower abs"],"secondary":[],"equip":"Smith","tip":"Feet under the bar, legs straight up; lift the hips to push the bar up a few inches.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/smith-hip-raise-0.jpg","img/smith-hip-raise-1.jpg"],"steps":["Position a bench in the rack and load the bar to an appropriate weight. Lie down on the bench, placing the bottom of your feet against the bar. Unlock the bar and extend your legs. You may need to use your hands to assist you. For added stability grasp the sides of the Smith Machine. This will be your starting position.","Initiate the movement by rotating your pelvis, flexing your spine to raise your hips off of the bench. Maintain a slight bend in the knees throughout the motion.","After a brief pause, return the hips to the bench.","Repeat for the desired number of repetitions."]},{"id":"captains-chair","name":"Captain's Chair Knee Raise","group":"Core","primary":["Lower abs","Hip flexors"],"secondary":["Obliques"],"equip":"Machine","tip":"Back flat on the pad; curl the pelvis up at the top instead of only lifting the knees.","mine":false,"track":"bw","alt":[],"aka":["Vertical knee raise","Roman chair leg raise","Parallel bar knee raise"],"img":["img/captains-chair-0.jpg","img/captains-chair-1.jpg"],"steps":["Position your body on the vertical leg raise bench so that your forearms are resting on the pads next to the torso and holding on to the handles. Your arms will be bent at a 90 degree angle.","The torso should be straight with the lower back pressed against the pad of the machine and the legs extended pointing towards the floor. This will be your starting position.","Now as you breathe out, lift your legs up as you keep them extended. Continue this movement until your legs are roughly parallel to the floor and then hold the contraction for a second. Tip: Do not use any momentum or swinging as you perform this exercise.","Slowly go back to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."]},{"id":"hanging-pike","name":"Hanging Pike","group":"Core","primary":["Lower abs","Hip flexors"],"secondary":["Grip","Lats"],"equip":"Bodyweight","tip":"Advanced: straight legs up to the bar under control; no swinging.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/hanging-pike-0.jpg","img/hanging-pike-1.jpg"],"steps":["Hang from a chin-up bar with your legs and feet together using an overhand grip (palms facing away from you) that is slightly wider than shoulder width. Tip: You may use wrist wraps in order to facilitate holding on to the bar.","Now bend your knees at a 90 degree angle and bring the upper legs forward so that the calves are perpendicular to the floor while the thighs remain parallel to it. This will be your starting position.","Pull your legs up as you exhale until you almost touch your shins with the bar above you. Tip: Try to straighten your legs as much as possible while at the top.","Lower your legs as slowly as possible until you reach the starting position. Tip: Avoid swinging and using momentum at all times.","Repeat for the recommended amount of repetitions."]},{"id":"hanging-alt-knee-raise","name":"Hanging Alternating Knee Raise","group":"Core","primary":["Lower abs","Hip flexors"],"secondary":["Grip"],"equip":"Bodyweight","tip":"Hang still and drive one knee up, then the other, quickly but without swinging.","mine":false,"track":"bw","alt":[],"aka":["Wind sprints"],"img":["img/hanging-alt-knee-raise-0.jpg","img/hanging-alt-knee-raise-1.jpg"],"steps":["Hang from a pull-up bar using a pronated grip. Your arms and legs should be extended. This will be your starting position.","Begin by quickly raising one knee as high as you can. Do not swing your body or your legs. 3","Immediately reverse the motion, returning that leg to the starting position. Simultaneously raise the opposite knee as high as possible.","Continue alternating between legs until the set is complete."]},{"id":"gorilla-chin-crunch","name":"Gorilla Chin-Up Crunch","group":"Core","primary":["Abs","Lats"],"secondary":["Biceps","Grip"],"equip":"Bodyweight","tip":"Pull up and crunch the knees to the chest at the same time; lower both slowly.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/gorilla-chin-crunch-0.jpg","img/gorilla-chin-crunch-1.jpg"],"steps":["Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width.","Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position.","As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going up as soon as your nose is at the same level as the bar. Tip: When you get to this point you should also be finishing the crunch at the same time.","Slowly start to inhale as you return to the starting position.","Repeat for the recommended amount of repetitions."]},{"id":"ball-knee-tuck","name":"Stability Ball Knee Tuck","group":"Core","primary":["Lower abs"],"secondary":["Hip flexors","Shoulders"],"equip":"Other","tip":"Shins on the ball in a push-up position; roll the knees to the chest, hips stay level.","mine":false,"track":"bw","alt":[],"aka":["Ball pull-in","Swiss ball tuck"],"img":["img/ball-knee-tuck-0.jpg","img/ball-knee-tuck-1.jpg"],"steps":["Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position.","Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be your starting position.","While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles. Squeeze your abs and hold that position for a second.","Now slowly straighten your legs, rolling the ball back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]},{"id":"trx-knee-tuck","name":"TRX Knee Tuck","group":"Core","primary":["Lower abs"],"secondary":["Shoulders"],"equip":"Other","tip":"Feet in the straps in a plank; pull the knees in without letting the hips sag.","mine":false,"track":"bw","alt":[],"aka":["Suspended reverse crunch","Suspension knee tuck"],"img":["img/trx-knee-tuck-0.jpg","img/trx-knee-tuck-1.jpg"],"steps":["Secure a set of suspension straps with the handles hanging about a foot off of the ground. Move yourself into a pushup plank position facing away from the rack.","Place your feet into the handles. You should maintain a straight posture, not allowing the hips to sag. This will be your starting position.","Begin the movement by flexing the knees and hips, drawing the knees to your torso. As you do so, anteriorly tilt your pelvis, allowing your spine to flex.","At the top of the controlled motion, return to the starting position."],"x":1},{"id":"flutter-kicks","name":"Flutter Kicks","group":"Core","primary":["Lower abs","Hip flexors"],"secondary":[],"equip":"Bodyweight","tip":"Heels a few inches up, lower back pressed down; small quick kicks.","mine":false,"track":"bw","alt":[],"aka":["Scissor kicks","Scissor kick"],"img":["img/flutter-kicks-0.jpg","img/flutter-kicks-1.jpg"],"steps":["To begin, lie down with your back pressed against the floor or on an exercise mat (optional). Your arms should be fully extended to the sides with your palms facing down. Note: The arms should be stationary the entire time.","With a slight bend at the knees, lift your legs up so that your heels are about 6 inches off the ground. This is the starting position.","Now lift your left leg up to about a 45 degree angle while your right leg is lowered until the heel is about 2-3 inches from the ground.","Switch movements by raising your right leg up and lowering your left leg. Remember to breathe while performing this exercise.","Repeat for the recommended amount of repetitions."]},{"id":"sit-up","name":"Sit-Up","group":"Core","primary":["Abs","Hip flexors"],"secondary":[],"equip":"Bodyweight","tip":"Feet held down; curl up one part of the spine at a time and roll back down slowly.","mine":false,"track":"bw","alt":[],"aka":["Situp","Sit ups"],"img":["img/sit-up-0.jpg","img/sit-up-1.jpg"],"steps":["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.","Place your hands behind your head and lock them together by clasping your fingers. This is the starting position.","Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise.","Once you feel the contraction for a second, lower your upper body back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."]},{"id":"three-quarter-sit-up","name":"3/4 Sit-Up","group":"Core","primary":["Abs"],"secondary":["Hip flexors"],"equip":"Bodyweight","tip":"Stop about three quarters of the way up, so the abs stay working at the top.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/three-quarter-sit-up-0.jpg","img/three-quarter-sit-up-1.jpg"],"steps":["Lie down on the floor and secure your feet. Your legs should be bent at the knees.","Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position.","Flex your hips and spine to raise your torso toward your knees.","At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.","Repeat for the recommended amount of repetitions."]},{"id":"v-up","name":"V-Up","group":"Core","primary":["Abs","Hip flexors"],"secondary":[],"equip":"Bodyweight","tip":"Arms and legs meet over the hips; keep the legs straight and lower both slowly.","mine":false,"track":"bw","alt":[],"aka":["Jackknife sit-up","Jackknife","V up"],"img":["img/v-up-0.jpg","img/v-up-1.jpg"],"steps":["Lie flat on the floor (or exercise mat) on your back with your arms extended straight back behind your head and your legs extended also. This will be your starting position.","As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position. Tip: The legs should be extended and lifted at approximately a 35-45 degree angle from the floor and the arms should be extended and parallel to your legs. The upper torso should be off the floor.","While inhaling, lower your arms and legs back to the starting position.","Repeat for the recommended amount of repetitions."]},{"id":"janda-sit-up","name":"Janda Sit-Up","group":"Core","primary":["Upper abs"],"secondary":[],"equip":"Bodyweight","tip":"Squeeze glutes and hamstrings hard to switch the hip flexors off; take 3 to 6 seconds up.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/janda-sit-up-0.jpg","img/janda-sit-up-1.jpg"],"steps":["Position your body on the floor in the basic sit-up position; knees to a ninety degree angle with feet flat on the floor and arms either crossed over your chest or to the sides. This will be your starting position.","As you strongly tighten your glutes and hamstrings, fill your lungs with air and in a slow (three to six second count) ascent, slowly exhale. Tip: It is important to tighten the glutes and hamstrings as this will cause the hip flexors to be inactivated in a process called reciprocal inhibition, which basically means that opposite muscles to the contracted ones will relax.","As you inhale, slowly go back in a controlled manner to the starting position.","Repeat for the recommended amount of repetitions."]},{"id":"frog-sit-up","name":"Frog Sit-Up","group":"Core","primary":["Upper abs"],"secondary":[],"equip":"Bodyweight","tip":"Soles together, knees out to the sides: the hip flexors can't help much, so the abs work.","mine":false,"track":"bw","alt":[],"aka":["Butterfly sit-up"],"img":["img/frog-sit-up-0.jpg","img/frog-sit-up-1.jpg"],"steps":["Lie with your back flat on the floor (or exercise mat) and your legs extended in front of you.","Now bend at the knees and place your outer thighs by the floor (or mat) as you make the soles of your feet touch each other.","Now try pushing both soles and bringing them up as near you as possible while you keep the outer thighs on the floor (or at least almost touching it). Tip: In this position your legs should create a diamond shape.","Now, cross your arms in front of you by touching the opposite shoulders. This will be your starting position.","As you exhale flatten your lower back to the floor while curling the torso upwards. Tip: This will be like performing the first 1/4 movement of a sit up. Hold at the top position for a second.","As you inhale, slowly lower back to the starting position."]},{"id":"otis-up","name":"Otis-Up","group":"Core","primary":["Abs"],"secondary":["Shoulders","Triceps"],"equip":"Other","tip":"Sit up with a plate at the chest and press it overhead at the top; lower both slowly.","mine":false,"track":"weight","alt":[],"aka":["Sit-up with press"],"img":["img/otis-up-0.jpg","img/otis-up-1.jpg"],"steps":["Secure your feet and lay back on the floor. Your knees should be bent. Hold a weight with both hands to your chest. This will be your starting position.","Initiate the movement by flexing the hips and spine to raise your torso up from the ground.","As you move up, press the weight up so that it is above your head at the top of the movement.","Return the weight to your chest as you reverse the sit-up motion, ensuring not to go all the way down to the floor."]},{"id":"press-sit-up","name":"Barbell Press Sit-Up","group":"Core","primary":["Abs"],"secondary":["Shoulders","Triceps","Chest"],"equip":"Barbell","tip":"On a sit-up bench with a light bar on the chest; press it up as you sit up.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/press-sit-up-0.jpg","img/press-sit-up-1.jpg"],"steps":["To begin, lie down on a bench with a barbell resting on your chest. Position your legs so they are secure on the extension of the abdominal bench. This is the starting position.","While inhaling, tighten your abdominals and glutes. Simultaneously curl your torso as you do when performing a sit-up and press the barbell to an overhead position while exhaling. Tip: Use your arms to push the barbell out as you perform this exercise while still focusing on the abdominal muscles.","Lower your upper body back down to the starting position while bringing the barbell back down to your torso. Remember to breathe in while lowering the body.","Repeat for the recommended amount of repetitions."],"x":1},{"id":"band-sit-up","name":"Band-Resisted Decline Sit-Up","group":"Core","primary":["Abs"],"secondary":["Hip flexors"],"equip":"Other","tip":"Bands fixed to the bench base; the pull gets harder as you come up.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/band-sit-up-0.jpg","img/band-sit-up-1.jpg"],"steps":["Start out by strapping the bands around the base of the decline bench. Place the handles towards the inside of the decline bench so that when lying down, you can reach for both of them.","Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your wrist to a neutral grip (palms facing the torso). Note: Your arms should remain stationary throughout the exercise. This is the starting position.","Move your torso upward until your upper body is perpendicular to the floor while exhaling. Hold the contraction for a second and lower your upper body back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"x":1},{"id":"barbell-rollout-knees","name":"Barbell Rollout (from the knees)","group":"Core","primary":["Abs"],"secondary":["Lats","Shoulders"],"equip":"Barbell","tip":"Light plates that roll; go only as far as the lower back stays flat, then pull back with the abs.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/barbell-rollout-knees-0.jpg","img/barbell-rollout-knees-1.jpg"],"steps":["Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.","Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.","Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.","After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times."]},{"id":"barbell-rollout-toes","name":"Barbell Rollout (from the toes)","group":"Core","primary":["Abs"],"secondary":["Lats","Shoulders"],"equip":"Barbell","tip":"The hardest rollout: start from a push-up position; master the knee version first.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/barbell-rollout-toes-0.jpg","img/barbell-rollout-toes-1.jpg"],"steps":["For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.","While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don't, you will work out your shoulders and back more than the abs.","After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.","Repeat for the recommended amount of repetitions."]},{"id":"barbell-rollout-bench","name":"Barbell Rollout from a Bench","group":"Core","primary":["Abs"],"secondary":["Lats","Shoulders","Glutes"],"equip":"Barbell","tip":"Knees on the bench end, bar on the floor; roll out and back with a flat lower back.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/barbell-rollout-bench-0.jpg","img/barbell-rollout-bench-1.jpg"],"steps":["Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position.","To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement.","When the bar has been moved as far forward as possible, return to the starting position."]},{"id":"trx-fallout","name":"TRX Fallout","group":"Core","primary":["Abs"],"secondary":["Shoulders","Lats"],"equip":"Other","tip":"Arms straight in the straps; lean forward letting the arms rise, ribs down, then pull back.","mine":false,"track":"bw","alt":[],"aka":["Suspended fallout"],"img":["img/trx-fallout-0.jpg","img/trx-fallout-1.jpg"],"steps":["Adjust the straps so the handles are at an appropriate height, below waist level.","Begin standing and grasping the handles. Lean into the straps, moving to an incline push-up position. This will be your starting position.","Keeping your arms straight, lean further into the suspension straps, bringing your body closer to the ground, allowing your shoulders to extend, raising your arms up and over your head.","Maintain a neutral spine and keep the rest of your body straight, your shoulders being the only joints allowed to move.","Pause during the peak contraction, and then return to the starting position."],"x":1},{"id":"side-plank","name":"Side Plank","group":"Core","primary":["Obliques"],"secondary":["Shoulders","Glutes (side)"],"equip":"Bodyweight","tip":"Elbow under the shoulder, body in one line; push the hips up and hold. Time each side.","mine":false,"track":"time","alt":[],"aka":["Side bridge"],"img":["img/side-plank-0.jpg","img/side-plank-1.jpg"],"steps":["Lie on your side with your legs straight and stacked.","Prop yourself up on your forearm with the elbow under your shoulder.","Lift your hips so your body makes a straight line from the head to the feet.","Hold while breathing, then switch sides. Bend the knees to make it easier."]},{"id":"push-up-side-plank","name":"Push-Up to Side Plank","group":"Core","primary":["Obliques","Chest"],"secondary":["Triceps","Shoulders"],"equip":"Bodyweight","tip":"One push-up, then turn into a side plank with the arm up; alternate sides.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/push-up-side-plank-0.jpg","img/push-up-side-plank-1.jpg"],"steps":["Get into pushup position on the toes with your hands just outside of shoulder width.","Perform a pushup by allowing the elbows to flex. As you descend, keep your body straight.","Do one pushup and as you come up, shift your weight on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank.","Lower the arm back to the floor for another pushup and then twist to the other side.","Repeat the series, alternating each side, for 10 or more reps."]},{"id":"butt-ups","name":"Butt-Ups (forearm plank pike)","group":"Core","primary":["Abs"],"secondary":["Shoulders"],"equip":"Bodyweight","tip":"From a forearm plank, lift the hips high by squeezing the abs, then back to a straight plank.","mine":false,"track":"bw","alt":[],"aka":["Plank pike"],"img":["img/butt-ups-0.jpg","img/butt-ups-1.jpg"],"steps":["Begin a pushup position but with your elbows on the ground and resting on your forearms. Your arms should be bent at a 90 degree angle.","Arch your back slightly out rather than keeping your back completely straight.","Raise your glutes toward the ceiling, squeezing your abs tightly to close the distance between your ribcage and hips. The end result will be that you'll end up in a high bridge position. Exhale as you perform this portion of the movement.","Lower back down slowly to your starting position as you breathe in. Tip: Don't let your back sag downwards.","Repeat for the recommended amount of repetitions."]},{"id":"spider-crawl","name":"Spider Crawl","group":"Core","primary":["Obliques","Abs"],"secondary":["Chest","Shoulders","Triceps"],"equip":"Bodyweight","tip":"Low push-up position; bring each knee out toward its elbow as you crawl forward.","mine":false,"track":"bw","alt":[],"aka":["Spiderman crawl"],"img":["img/spider-crawl-0.jpg","img/spider-crawl-1.jpg"],"steps":["Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position.","Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible.","Return this leg to the starting position and repeat on the opposite side."]},{"id":"mountain-climbers","name":"Mountain Climbers","group":"Core","primary":["Abs","Hip flexors"],"secondary":["Shoulders","Quads"],"equip":"Bodyweight","tip":"Hands under the shoulders, hips level; drive the knees in fast without bouncing the hips.","mine":false,"track":"time","alt":[],"aka":["Mountain climber"],"img":["img/mountain-climbers-0.jpg","img/mountain-climbers-1.jpg"],"steps":["Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.","Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds."]},{"id":"db-side-bend","name":"Dumbbell Side Bend","group":"Core","primary":["Obliques"],"secondary":[],"equip":"Dumbbell","tip":"One dumbbell only; bend straight to the side, no leaning forward. Do both sides.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/db-side-bend-0.jpg","img/db-side-bend-1.jpg"],"steps":["Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.","While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.","Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.","Repeat for the recommended amount of repetitions and then change hands."]},{"id":"barbell-side-bend","name":"Barbell Side Bend","group":"Core","primary":["Obliques"],"secondary":["Lower back"],"equip":"Barbell","tip":"Light bar on the back; bend straight to the side, hips still.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/barbell-side-bend-0.jpg","img/barbell-side-bend-1.jpg"],"steps":["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.","While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.","Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.","Repeat for the recommended amount of repetitions."]},{"id":"ball-side-bend","name":"Weighted Side Bend on a Ball","group":"Core","primary":["Obliques"],"secondary":[],"equip":"Other","tip":"Side on the ball, feet braced; lift the shoulder toward the hip holding a plate.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/ball-side-bend-0.jpg","img/ball-side-bend-1.jpg"],"steps":["To begin, lie down on an exercise ball with your left side of the torso (waist, hips and shoulder) pressed against the ball.","Your feet should be on the floor while your legs are crossed and hanging from the ball. Hold a weighted plate with your right hand directly to the right side of your head. Tip: Make sure the smooth side of the plate is resting against your head.","Place your left arm across your torso so that your palm is on your obliques. There should be a right angle between your left forearm and upper arm. This is the starting position.","Raise the side of your torso up by laterally flexing at the waist while exhaling.","Hold the contraction for a second and slowly lower yourself back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."]},{"id":"seated-barbell-twist","name":"Seated Barbell Twist","group":"Core","primary":["Obliques"],"secondary":[],"equip":"Barbell","tip":"Empty bar on the shoulders; turn the chest slowly, hips facing forward.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/seated-barbell-twist-0.jpg","img/seated-barbell-twist-1.jpg"],"steps":["Start out by sitting at the end of a flat bench with a barbell placed on top of your thighs. Your feet should be shoulder width apart from each other.","Grip the bar with your palms facing down and make sure your hands are wider than shoulder width apart from each other. Begin to lift the barbell up over your head until your arms are fully extended.","Now lower the barbell behind your head until it is resting along the base of your neck. This is the starting position.","While keeping your feet and head stationary, move your waist from side to side so that your oblique muscles feel the contraction. Only move from side to side as far as your waist will allow you to go. Stretching or moving too far can cause an injury to occur. Tip: Use a slow and controlled motion.","Remember to breathe out while twisting your body to the side and in when moving back to the starting position.","Repeat for the recommended amount of repetitions."]},{"id":"plate-twist","name":"Plate Twist","group":"Core","primary":["Obliques"],"secondary":["Abs"],"equip":"Other","tip":"Seated, feet up, plate in front; turn side to side, touching the plate down beside the hip.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/plate-twist-0.jpg","img/plate-twist-1.jpg"],"steps":["Lie down on the floor or an exercise mat with your legs fully extended and your upper body upright. Grab the plate by its sides with both hands out in front of your abdominals with your arms slightly bent.","Slowly cross your legs near your ankles and lift them up off the ground. Your knees should also be bent slightly. Note: Move your upper body back slightly to help keep you balanced turning this exercise. This is the starting position.","Move the plate to the left side and touch the floor with it. Breathe out as you perform that movement.","Come back to the starting position as you breathe in and then repeat the movement but this time to the right side of the body. Tip: Use a slow controlled movement at all times. Jerking motions can injure the back.","Repeat for the recommended amount of repetitions."]},{"id":"landmine-180","name":"Landmine Rotation","group":"Core","primary":["Obliques"],"secondary":["Shoulders","Glutes","Lower back"],"equip":"Barbell","tip":"Arms long, turn the hips and chest together to bring the bar from one hip to the other.","mine":false,"track":"weight","alt":[],"aka":["Landmine 180","Landmine twist"],"img":["img/landmine-180-0.jpg","img/landmine-180-1.jpg"],"steps":["Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.","Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position.","Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise.","Reverse the motion to swing the weight all the way to the opposite side.","Continue alternating the movement until the set is complete."]},{"id":"spell-caster","name":"Spell Caster","group":"Core","primary":["Obliques"],"secondary":["Shoulders","Glutes"],"equip":"Dumbbell","tip":"Light dumbbells; sweep them from one hip up and across to the other side, arms straight.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/spell-caster-0.jpg","img/spell-caster-1.jpg"],"steps":["Hold a dumbbell in each hand with a pronated grip. Your feet should be wide with your hips and knees extended. This will be your starting position.","Begin the movement by pulling both of the dumbbells to one side next to your hip, rotating your torso.","Keeping your arms straight and the dumbbells parallel to the ground, rotate your torso to swing the weights to your opposite side.","Continue alternating, rotating from one side to the other until the set is complete."]},{"id":"mb-partner-twist","name":"Medicine Ball Partner Twist","group":"Core","primary":["Obliques"],"secondary":["Shoulders"],"equip":"Other","tip":"Back to back with a partner; turn and pass the ball, then turn the other way.","mine":false,"track":"weight","alt":[],"aka":["Medicine ball full twist"],"img":["img/mb-partner-twist-0.jpg","img/mb-partner-twist-1.jpg"],"steps":["For this exercise you will need a medicine ball and a partner. Stand back to back with your partner, spaced 2-3 feet apart. This will be your starting position.","Hold the ball in front of the trunk. Open the hips and turn the shoulders at the same time as your partner.","For full rotation, you and your partner should twist in the same direction, i.e. counter-clockwise.","Pass the ball to your partner, and both of you can now twist in the opposite direction to repeat the procedure."],"x":1},{"id":"kb-windmill","name":"Kettlebell Windmill","group":"Core","primary":["Obliques"],"secondary":["Shoulders","Glutes","Hamstrings"],"equip":"Other","tip":"Bell locked out overhead, eyes on it; push the hips out to the side and reach the free hand down.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/kb-windmill-0.jpg","img/kb-windmill-1.jpg"],"steps":["Place a kettlebell in front of your lead foot and clean and press it overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward. Press it overhead by extending the elbow.","Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell. Bending at the hip to one side, sticking your butt out, slowly lean until you can touch the floor with your free hand. Keep your eyes on the kettlebell that you hold over your head at all times.","Pause for a second after reaching the ground and reverse the motion back to the starting position."]},{"id":"kb-windmill-advanced","name":"Kettlebell Windmill (bell held up throughout)","group":"Core","primary":["Obliques"],"secondary":["Shoulders","Glutes","Hamstrings"],"equip":"Other","tip":"Press the bell up and keep it locked out the whole set; go only as low as the hamstrings allow.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/kb-windmill-advanced-0.jpg","img/kb-windmill-advanced-1.jpg"],"steps":["Clean and press a kettlebell overhead with one arm.","Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell.","Lower yourself as far as possible.","Pause for a second and reverse the motion back to the starting position."],"x":1},{"id":"kb-windmill-double","name":"Double Kettlebell Windmill","group":"Core","primary":["Obliques"],"secondary":["Shoulders","Glutes","Hamstrings"],"equip":"Other","tip":"One bell overhead, one on the floor; reach down for the low bell keeping the top arm locked.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/kb-windmill-double-0.jpg","img/kb-windmill-double-1.jpg"],"steps":["Place a kettlebell in front of your front foot and clean and press a kettlebell overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward.","Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell.","Bending at the hip to one side, sticking your butt out, slowly lean until you can retrieve the kettlebell from the floor. Keep your eyes on the kettlebell that you hold over your head at all times.","Pause for a second after retrieving the kettlebell from the ground and reverse the motion back to the starting position."],"x":1},{"id":"kb-figure-8","name":"Kettlebell Figure 8","group":"Core","primary":["Core","Obliques"],"secondary":["Hamstrings","Shoulders"],"equip":"Other","tip":"Hips back, flat back; pass the bell between the legs from hand to hand in a figure 8.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/kb-figure-8-0.jpg","img/kb-figure-8-1.jpg"],"steps":["Place one kettlebell between your legs and take a wider than shoulder width stance. Bend over by pushing your butt out and keeping your back flat.","Pick up a kettlebell and pass it to your other hand between your legs. The receiving hand should reach from behind the legs. Go back and forth for several repetitions."]},{"id":"kb-pass-between-legs","name":"Kettlebell Pass Between the Legs","group":"Core","primary":["Core","Obliques"],"secondary":["Glutes","Hamstrings","Shoulders"],"equip":"Other","tip":"Hinge with a flat back and pass the bell between the legs in a W, back and forth.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/kb-pass-between-legs-0.jpg","img/kb-pass-between-legs-1.jpg"],"steps":["Place one kettlebell between your legs and take a comfortable stance. Bend over by pushing your butt out and keeping your back flat.","Pick up a kettlebell and pass it to your other hand between your legs, in the fashion of a \"W\". Go back and forth for several repetitions."]},{"id":"bent-press","name":"Kettlebell Bent Press","group":"Core","primary":["Obliques","Core"],"secondary":["Shoulders","Glutes","Hamstrings"],"equip":"Other","tip":"Advanced: lean away and under the bell until the arm is straight, then stand up with it locked out.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/bent-press-0.jpg","img/bent-press-1.jpg"],"steps":["Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.","Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground.","Return to an upright position, with the kettlebell above your head. Return the kettlebell to the shoulder and repeat for the desired number of repetitions."],"x":1},{"id":"mb-slam","name":"Medicine Ball Slam (one arm)","group":"Core","primary":["Abs"],"secondary":["Lats","Shoulders"],"equip":"Other","tip":"Ball up overhead, then slam it down hard with the abs and lats; catch and repeat.","mine":false,"track":"weight","alt":[],"aka":["Ball slam"],"img":["img/mb-slam-0.jpg","img/mb-slam-1.jpg"],"steps":["Start in a standing position with a staggered, athletic stance. Hold a medicine ball in one hand, on the same side as your back leg. This will be your starting position.","Begin by winding the arm, raising the medicine ball above your head. As you do so, extend through the hips, knees, and ankles to load up for the slam.","At peak extension, flex the shoulders, spine, and hips to throw the ball hard into the ground directly in front of you.","Catch the ball on the bounce and continue for the desired number of repetitions."]},{"id":"mb-sit-up-throw","name":"Medicine Ball Sit-Up Throw","group":"Core","primary":["Abs"],"secondary":["Chest","Lats","Shoulders"],"equip":"Other","tip":"Ball held behind the head with both hands; sit up and throw it forward to a partner or a wall.","mine":false,"track":"weight","alt":[],"aka":["Supine overhead throw"],"img":["img/mb-sit-up-throw-0.jpg","img/mb-sit-up-throw-1.jpg"],"steps":["Lay on the ground on your back with your knees bent.","Hold the ball with both hands, extending the arms fully behind your head. This will be your starting position.","Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.","The ball can be thrown to a partner or bounced off of a wall."],"x":1},{"id":"mb-sit-up-throw-one","name":"Medicine Ball Sit-Up Throw (one arm)","group":"Core","primary":["Abs"],"secondary":["Chest","Lats","Shoulders"],"equip":"Other","tip":"Ball in one hand behind the head; sit up and throw it as far forward as you can.","mine":false,"track":"weight","alt":[],"aka":[],"img":["img/mb-sit-up-throw-one-0.jpg","img/mb-sit-up-throw-one-1.jpg"],"steps":["Lay on the ground on your back with your knees bent. Hold the ball with one hand, extending the arm fully behind your head. This will be your starting position.","Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.","The ball can be thrown to a partner or bounced off of a wall."],"x":1},{"id":"sledgehammer-swings","name":"Sledgehammer Swings","group":"Core","primary":["Abs","Obliques"],"secondary":["Shoulders","Lats","Forearms"],"equip":"Other","tip":"Hit a tyre: slide the top hand down as the hammer comes down, and switch sides.","mine":false,"track":"bw","alt":[],"aka":["Tyre hits","Tire hits"],"img":["img/sledgehammer-swings-0.jpg","img/sledgehammer-swings-1.jpg"],"steps":["You will need a tire and a sledgehammer for this exercise. Stand in front of the tire about two feet away from it with a staggered stance. Grip the sledgehammer.","If you are right handed, your left hand should be at the bottom of the handle, and your right hand should be choking up closer to the head.","As you bring the sledge up, your right hand slides toward the head; as you swing down, your right hand will slide down to join your left hand. Slam it down as hard as you can against the tire. Control the bounce of the hammer off of the tire.","Repeat on the other side."],"x":1},{"id":"dead-bug","name":"Dead Bug","group":"Core","primary":["Abs","Core"],"secondary":["Hip flexors"],"equip":"Bodyweight","tip":"Lower back glued to the floor; reach the opposite arm and leg out slowly, breathe out.","mine":false,"track":"bw","alt":[],"aka":[],"img":["img/dead-bug-0.jpg","img/dead-bug-1.jpg"],"steps":["Begin lying on your back with your hands extended above you toward the ceiling.","Bring your feet, knees, and hips up to 90 degrees.","Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.","Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.","Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.","Stay tight and return the working leg to the starting position."]},{"id":"stomach-vacuum","name":"Stomach Vacuum","group":"Core","primary":["Core"],"secondary":[],"equip":"Bodyweight","tip":"Breathe all the air out, pull the belly button in toward the spine and hold; small breaths.","mine":false,"track":"time","alt":[],"aka":["Vacuum"],"img":["img/stomach-vacuum-0.jpg","img/stomach-vacuum-1.jpg"],"steps":["To begin, stand straight with your feet shoulder width apart from each other. Place your hands on your hips. This is the starting position.","Now slowly inhale as much air as possible and then start to exhale as much as possible while bringing your stomach in as much as possible and hold this position. Try to visualize your navel touching your backbone.","One isometric contraction is around 20 seconds. During the 20 second hold, try to breathe normally. Then inhale and bring your stomach back to the starting position.","Once you have practiced this exercise, try to perform this exercise for longer than 20 seconds. Tip: You can work your way up to 40-60 seconds.","Repeat for the recommended amount of sets."]},{"id":"hollow-hold","name":"Hollow Body Hold","group":"Core","primary":["Abs","Core"],"secondary":["Hip flexors"],"equip":"Bodyweight","tip":"Lower back pressed down, arms by the ears, legs low; bend the knees to make it easier.","mine":false,"track":"time","alt":[],"aka":["Hollow hold","Hollow body"],"img":[],"steps":["Lie on your back with your arms straight up past your head and your legs straight.","Press your lower back into the floor, then lift your shoulders, arms and legs a few inches off the floor.","Keep the lower back pressed down the whole time; the lower the arms and legs, the harder it is.","Hold while breathing steadily. Bend the knees or bring the arms forward if the back starts to lift."]},{"id":"hollow-rock","name":"Hollow Body Rock","group":"Core","primary":["Abs","Core"],"secondary":["Hip flexors"],"equip":"Bodyweight","tip":"Hold the hollow shape and rock from the upper back to the hips without it breaking.","mine":false,"track":"bw","alt":[],"aka":["Hollow rocks"],"img":[],"steps":["Get into a hollow body hold: lower back pressed down, arms by your ears, legs straight and off the floor.","Without changing the shape, rock back toward your shoulders and forward toward your hips.","Keep the movement small and the body stiff, like the rocker of a chair.","Stop the set when the shape breaks (the legs drop or the back arches)."]},{"id":"l-sit","name":"L-Sit","group":"Core","primary":["Abs","Hip flexors"],"secondary":["Triceps","Quads"],"equip":"Bodyweight","tip":"On dip bars or the floor, push down, shoulders low, legs straight out in front. Tuck the knees to start.","mine":false,"track":"time","alt":[],"aka":["L sit","Tuck sit"],"img":[],"steps":["Sit between two dip bars, parallettes or on the floor with your hands beside your hips.","Press down through straight arms to lift your body, pushing the shoulders down away from your ears.","Lift your legs straight out in front so the body makes an L. Bend the knees (tuck sit) to make it easier.","Hold while breathing; lower with control."]},{"id":"dragon-flag","name":"Dragon Flag","group":"Core","primary":["Abs"],"secondary":["Lats","Hip flexors"],"equip":"Bodyweight","tip":"Advanced: on a bench holding behind your head, body straight from the shoulders; lower as slowly as you can.","mine":false,"track":"bw","alt":[],"aka":["Dragon flags"],"img":[],"steps":["Lie on a bench and grip the bench (or a post) behind your head.","Lift your hips and legs until your body is straight from the shoulders to the toes, weight on the upper back.","Keeping the body straight and the hips from bending, lower it as slowly as you can toward the bench.","Stop just above the bench and lift back up, or lower only (negatives) until you are strong enough.","Start with bent knees; this is an advanced exercise, so stop if the lower back hurts."],"x":1},{"id":"toes-to-bar","name":"Toes-to-Bar","group":"Core","primary":["Lower abs","Hip flexors"],"secondary":["Lats","Grip"],"equip":"Bodyweight","tip":"Hang, then lift the feet all the way to the bar; press the bar down with straight arms to help.","mine":false,"track":"bw","alt":[],"aka":["T2B","Toes to bar"],"img":[],"steps":["Hang from a pull-up bar with straight arms, hands about shoulder width.","Brace the abs and press the bar down a little with straight arms.","Curl the hips up and lift the feet until the toes touch the bar.","Lower the legs under control to the hang without swinging; bend the knees to make it easier."]},{"id":"hanging-windshield-wipers","name":"Hanging Windshield Wipers","group":"Core","primary":["Obliques","Lower abs"],"secondary":["Grip","Lats"],"equip":"Bodyweight","tip":"Advanced: legs up at the bar, then turn them slowly side to side like a wiper.","mine":false,"track":"bw","alt":[],"aka":["Windshield wipers"],"img":[],"steps":["Hang from a pull-up bar and lift your legs up so they point at the ceiling (or toward the bar).","Keeping the legs together, turn them slowly to one side, like a windscreen wiper.","Come back through the middle and turn to the other side.","Control the movement and do not swing; bend the knees to make it easier."],"x":1},{"id":"lying-windshield-wipers","name":"Lying Windshield Wipers","group":"Core","primary":["Obliques"],"secondary":["Lower abs"],"equip":"Bodyweight","tip":"Arms out wide, legs straight up; lower them to one side, shoulders stay down. Bend the knees to make it easier.","mine":false,"track":"bw","alt":[],"aka":["Windshield wipers"],"img":[],"steps":["Lie on your back with your arms out wide, palms down, and your legs straight up.","Keeping the shoulders on the floor, lower both legs together to one side.","Stop before the opposite shoulder lifts, then bring the legs back up and lower them to the other side.","Bend the knees to 90 degrees to make it easier."]},{"id":"copenhagen-plank","name":"Copenhagen Side Plank","group":"Core","primary":["Obliques","Adductors"],"secondary":["Shoulders"],"equip":"Bodyweight","tip":"Top leg on a bench, bottom leg free; lift the hips and hold. Knee on the bench to make it easier.","mine":false,"track":"time","alt":[],"aka":["Copenhagen plank","Copenhagen adductor"],"img":[],"steps":["Lie on your side next to a bench and place the inside of your top foot (or knee, for an easier version) on it.","Prop yourself up on your forearm, elbow under your shoulder.","Lift your hips so your body is in one straight line; the bottom leg can hang or lift to meet the bench.","Hold, then switch sides."]},{"id":"bird-dog","name":"Bird Dog","group":"Core","primary":["Core"],"secondary":["Lower back","Glutes"],"equip":"Bodyweight","tip":"On hands and knees, reach the opposite arm and leg out long without the hips tipping; slow.","mine":false,"track":"bw","alt":[],"aka":["Birddog","Quadruped arm and leg raise"],"img":[],"steps":["Get on your hands and knees, hands under the shoulders and knees under the hips, back flat.","Reach one arm forward and the opposite leg back until both are level with your body.","Keep the hips and shoulders square; do not let the lower back sag or the hips tip.","Hold a second, return slowly and switch sides."]},{"id":"bear-plank","name":"Bear Plank Hold","group":"Core","primary":["Core"],"secondary":["Shoulders","Quads"],"equip":"Bodyweight","tip":"On hands and toes with the knees an inch off the floor, back flat; hold and breathe.","mine":false,"track":"time","alt":[],"aka":["Bear hold","Hover"],"img":[],"steps":["Get on your hands and knees, hands under the shoulders and knees under the hips.","Tuck your toes, brace your abs and lift your knees an inch or two off the floor.","Keep your back flat and hold while breathing steadily."]},{"id":"plank-shoulder-taps","name":"Plank Shoulder Taps","group":"Core","primary":["Core","Obliques"],"secondary":["Shoulders"],"equip":"Bodyweight","tip":"High plank, feet wide; tap each shoulder without the hips rocking.","mine":false,"track":"bw","alt":[],"aka":["Shoulder taps"],"img":[],"steps":["Start in a high plank on your hands with your feet a little wider than hip width.","Lift one hand and tap the opposite shoulder, keeping your hips still.","Put the hand down and repeat with the other hand.","Widen your feet to make it easier, bring them together to make it harder."]},{"id":"side-plank-hip-dips","name":"Side Plank Hip Dips","group":"Core","primary":["Obliques"],"secondary":["Shoulders","Glutes (side)"],"equip":"Bodyweight","tip":"In a side plank, lower the hip almost to the floor and lift it back up; both sides.","mine":false,"track":"bw","alt":[],"aka":["Hip dips"],"img":[],"steps":["Get into a side plank on your forearm, elbow under the shoulder, feet stacked.","Lower your hip toward the floor without touching it.","Lift it back up past the straight line, squeezing the side of your waist.","Do all the reps, then switch sides."]},{"id":"stir-the-pot","name":"Stir the Pot","group":"Core","primary":["Abs","Core"],"secondary":["Shoulders"],"equip":"Other","tip":"Forearms on a stability ball in a plank; draw small circles with the elbows, body still.","mine":false,"track":"bw","alt":[],"aka":[],"img":[],"steps":["Get into a plank with your forearms on a stability ball and your feet on the floor.","Keeping your body still and straight, move your elbows in small circles, as if stirring a pot.","Go one way for the set, then the other way; make the circles bigger to make it harder."]},{"id":"plank-up-down","name":"Plank Up-Down","group":"Core","primary":["Core"],"secondary":["Triceps","Shoulders","Chest"],"equip":"Bodyweight","tip":"From a forearm plank push up to the hands one arm at a time, then back down; hips steady.","mine":false,"track":"bw","alt":[],"aka":["Walking plank","Commandos"],"img":[],"steps":["Start in a forearm plank.","Place one hand on the floor and push up, then the other, until you are in a high plank.","Lower back down to your forearms one arm at a time.","Keep your hips steady; start with the other arm on the next rep."]},{"id":"suitcase-carry","name":"Suitcase Carry","group":"Core","primary":["Obliques","Core"],"secondary":["Grip","Upper traps"],"equip":"Dumbbell","tip":"A heavy dumbbell or kettlebell in one hand; walk tall without leaning. Swap hands.","mine":false,"track":"time","alt":[],"aka":["One-arm farmer walk","Suitcase walk"],"img":[],"steps":["Pick up a heavy dumbbell or kettlebell in one hand, like a suitcase.","Stand tall with your shoulders level and your free arm relaxed.","Walk slowly for the time or distance without leaning toward or away from the weight.","Switch hands and walk back."]},{"id":"ball-pike","name":"Stability Ball Pike","group":"Core","primary":["Lower abs","Abs"],"secondary":["Shoulders","Hip flexors"],"equip":"Other","tip":"Toes on the ball in a push-up position; lift the hips high with straight legs, then back to a plank.","mine":false,"track":"bw","alt":[],"aka":["Swiss ball pike"],"img":[],"steps":["Start in a push-up position with your shins or toes on a stability ball.","Keeping your legs straight, lift your hips high so your body makes an upside-down V, rolling the ball toward your hands.","Lower back to the plank slowly without letting the hips sag."]},{"id":"hanging-oblique-knee-raise","name":"Hanging Oblique Knee Raise","group":"Core","primary":["Obliques","Lower abs"],"secondary":["Grip","Hip flexors"],"equip":"Bodyweight","tip":"Hang, then lift the knees up and to one side, curling the hips; alternate sides.","mine":false,"track":"bw","alt":[],"aka":["Hanging side knee raise"],"img":[],"steps":["Hang from a pull-up bar with straight arms.","Lift your knees up and toward one side, curling your hips up as you go.","Lower under control without swinging and repeat to the other side."]},{"id":"rkc-plank","name":"RKC Plank","group":"Core","primary":["Abs","Core"],"secondary":["Glutes","Shoulders"],"equip":"Bodyweight","tip":"A plank at full tension: elbows pulled toward the toes, glutes and quads squeezed hard; 10 to 20 s.","mine":false,"track":"time","alt":[],"aka":["Hard-style plank","Long-lever plank"],"img":[],"steps":["Get into a forearm plank with your elbows under the shoulders.","Pull your elbows toward your toes and your toes toward your elbows without moving them.","Squeeze your glutes and thighs as hard as you can and tuck your pelvis.","Hold for 10 to 20 seconds of full tension, breathing in short breaths."]},{"id":"turkish-get-up","name":"Turkish Get-Up","group":"Core","primary":["Core","Obliques"],"secondary":["Shoulders","Glutes"],"equip":"Other","tip":"Light first, eyes on the bell, arm locked the whole way; stand up step by step and reverse it.","mine":false,"track":"weight","alt":[],"aka":["TGU","Get-up"],"img":[],"steps":["Lie on your back holding a light kettlebell straight up in one hand, the knee on that side bent.","Keeping your eyes on the bell and the arm locked, roll onto the opposite elbow, then onto the hand.","Lift your hips, sweep the straight leg under you to a kneeling position, then stand up.","Reverse every step to lie back down; do the same on the other side.","Learn it with no weight or a shoe balanced on the fist first."],"x":1},{"id":"rowing-machine","name":"Rowing Machine (erg)","group":"Cardio","primary":["Heart & lungs","Back","Legs"],"secondary":["Core","Arms"],"equip":"Cardio","tip":"Legs → body → arms, then arms → body → legs. Damper 4–6.","mine":true,"track":"time","alt":[],"aka":[],"img":["img/rowing-machine-0.jpg","img/rowing-machine-1.jpg"],"steps":["To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips.","There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend your legs while bringing your hands to your upper abdominal area, squeezing your shoulders back as you do so. To avoid straining your back, use primarily your leg and hip muscles.","The recovery phase simply involves straightening your arms, bending the knees, and bringing your body forward again as you transition back into the first phase."],"video":"4zWu1yuJ0_g"},{"id":"treadmill","name":"Treadmill — walk / incline walk / run","group":"Cardio","primary":["Heart & lungs","Legs"],"secondary":["Glutes","Calves"],"equip":"Cardio","tip":"Incline walk (10–12 %, 5 km/h) is the easiest fat-loss cardio on the joints.","mine":false,"track":"time","alt":[],"aka":[],"img":["img/treadmill-0.jpg","img/treadmill-1.jpg"],"steps":["To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.","Treadmills offer convenience, cardiovascular benefits, and usually have less impact than walking outside. When walking, you should move at a moderate to fast pace, not a leisurely one. Being an activity of lower intensity, walking doesn't burn as many calories as some other activities, but still provides great benefit. A 150 lb person will burn about 175 calories walking 4 miles per hour for 30 minutes, compared to 450 calories running twice as fast. Maintain proper posture as you walk, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate."]},{"id":"stationary-bike","name":"Stationary Bike","group":"Cardio","primary":["Heart & lungs","Quads"],"secondary":["Glutes","Calves"],"equip":"Cardio","tip":"Seat height: slight knee bend at the bottom of the pedal stroke.","mine":false,"track":"time","alt":[],"aka":[],"img":["img/stationary-bike-0.jpg","img/stationary-bike-1.jpg"],"steps":["To begin, seat yourself on the bike and adjust the seat to your height.","Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity."]},{"id":"stair-climber","name":"Stair Climber","group":"Cardio","primary":["Heart & lungs","Glutes","Quads"],"secondary":["Calves"],"equip":"Cardio","tip":"Hands light on the rails, stand tall.","mine":false,"track":"time","alt":[],"aka":[],"img":["img/stair-climber-0.jpg","img/stair-climber-1.jpg"],"steps":["To begin, step onto the stairmaster and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise.","Pump your legs up and down in an established rhythm, driving the pedals down but not all the way to the floor. It is recommended that you maintain your grip on the handles so that you don't fall. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.","Stairmasters offer convenience, cardiovascular benefits, and usually have less impact than running outside. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking."]},{"id":"elliptical","name":"Elliptical","group":"Cardio","primary":["Heart & lungs","Legs"],"secondary":["Arms"],"equip":"Cardio","tip":"Low impact; push and pull the handles for a full-body effect.","mine":false,"track":"time","alt":[],"aka":[],"img":["img/elliptical-0.jpg","img/elliptical-1.jpg"],"steps":["To begin, step onto the elliptical and select the desired option from the menu. Most ellipticals have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.","The handles can be used to monitor your heart rate to help you stay at an appropriate intensity."]},{"id":"jump-rope","name":"Jump Rope","group":"Cardio","primary":["Heart & lungs","Calves"],"secondary":["Shoulders","Core"],"equip":"Cardio","tip":"Small hops, wrists do the work.","mine":false,"track":"time","alt":[],"aka":[],"img":["img/jump-rope-0.jpg","img/jump-rope-1.jpg"],"steps":["Hold an end of the rope in each hand. Position the rope behind you on the ground. Raise your arms up and turn the rope over your head bringing it down in front of you. When it reaches the ground, jump over it. Find a good turning pace that can be maintained. Different speeds and techniques can be used to introduce variation.","Rope jumping is exciting, challenges your coordination, and requires a lot of energy. A 150 lb person will burn about 350 calories jumping rope for 30 minutes, compared to over 450 calories running."]}];
